insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('layoff-first-two-weeks-structure-sheet', 'Layoff First Two Weeks Structure Sheet', 'worksheet'::resource_kind, 'A planner for the first two weeks after losing a job, with a daily shape, a search window and a stop time.', 'Use it to give a client whose days just lost their frame a structure before the search swallows everything.', array['Adults']::text[], '30 minutes to plan, two weeks to use', 'The first days after a layoff often go one of two ways: twelve hours of applications a day or none at all. The sheet asks the client to set a wake time, a search window of two or three hours, a stop time, one body activity and one social contact a day, and to decide in advance who they will tell and how. Review which parts held. Watch for shame that disguises itself as busyness, and for a client who treats the stop time as optional; the structure is there so the search is a job with hours, not an identity.', '[{"id": "f0", "type": "textarea", "label": "My wake time, start time and stop time for the search each day:"}, {"id": "f1", "type": "textarea", "label": "Two or three hours of search tasks, listed, and where I will do them:"}, {"id": "f2", "type": "textarea", "label": "One thing I will do with my body and one person I will talk to each day:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell about the layoff this week, and the sentence I will use:"}, {"id": "f4", "type": "textarea", "label": "What I notice myself doing when the stop time comes:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what held, what slipped, and what I want to change:"}]'::jsonb, array['stress', 'routines', 'planning']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('what-still-makes-me-laugh-humor-inventory', 'What Still Makes Me Laugh Humor Inventory', 'worksheet'::resource_kind, 'An inventory of the people, shows, memories and small absurdities that still get a laugh, and where they have gone from the week.', 'Use it to help a client who has stopped laughing find out whether the humor left or just stopped being scheduled.', array['Adults', 'Teens']::text[], '20 minutes', 'Laughter is often the first thing a stressed or low client stops noticing they miss. The inventory walks through sources: people who make them laugh, shows or books, memories that still land, things their pet or child does, and the kind of absurdity they find funny. Then it asks when each last happened. Most clients discover the sources are intact and the access has been cut by schedule or isolation. Choose one to put back this week. Avoid turning it into a mood fix; it is a map of a part of them that is still there.', '[{"id": "f0", "type": "textarea", "label": "People who reliably make me laugh, and when I last spent time with them:"}, {"id": "f1", "type": "textarea", "label": "Shows, books, podcasts or comics that get me, and when I last watched or read one:"}, {"id": "f2", "type": "textarea", "label": "A memory that still makes me laugh when I replay it:"}, {"id": "f3", "type": "textarea", "label": "The kind of absurd or silly thing I find funny that others might not:"}, {"id": "f4", "type": "textarea", "label": "One source of laughter I will put back in my week, and when:"}, {"id": "f5", "type": "textarea", "label": "After a week: did I laugh, and what was different about those minutes?"}]'::jsonb, array['self-care', 'strengths', 'energy']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('empty-nest-week-redesign-page', 'Empty Nest Week Redesign Page', 'worksheet'::resource_kind, 'A week-planning page for a parent whose last child has left home, with the hours that emptied and what might fill them on purpose.', 'Use it to help a client turn the sudden quiet of an empty house into a week they chose rather than one that happened to them.', array['Adults']::text[], '40 minutes', 'When the last child leaves, the hours that used to be driving, cooking for four and waiting up become empty at once, and many parents fill them with worry about the child or with nothing. The page marks the hours that changed, names the roles that went with them, and asks what the client wanted twenty years ago and never had time for. Plan one new fixture a week, not a whole new life. Watch for a client who redesigns the week entirely around the child''s phone calls; that is the old week in disguise.', '[{"id": "f0", "type": "textarea", "label": "The hours in my week that used to belong to parenting and are now empty:"}, {"id": "f1", "type": "textarea", "label": "The roles I held in those hours (driver, cook, audience, referee) and which I miss:"}, {"id": "f2", "type": "textarea", "label": "Things I set aside years ago because there was no time:"}, {"id": "f3", "type": "textarea", "label": "One fixture I will add to this week, on which day and at what hour:"}, {"id": "f4", "type": "textarea", "label": "How I will handle the urge to fill the quiet by checking on them:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: how the new fixture felt, and what I want next:"}]'::jsonb, array['transitions', 'values', 'routines']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('tax-season-paperwork-pacing-sheet', 'Tax Season Paperwork Pacing Sheet', 'worksheet'::resource_kind, 'A pacing plan for the pile of forms, receipts and logins that tax season brings, broken into sittings with an end time.', 'Use it to help a client who freezes at financial paperwork get through it in planned sittings instead of one dreaded night.', array['Adults']::text[], '20 minutes to plan, several short sittings', 'Financial paperwork is a common avoidance pile, and the dread grows as the deadline gets closer. The sheet lists every document the client needs, where each one lives, and which ones require someone else. Then it sets sittings of twenty to forty minutes with a stop time and a small reward, and names who the client can ask when they hit a wall. Review the first sitting in session if you can. Watch for shame about last year''s late filing; it is the pile''s fuel and does not need to be solved before starting.', '[{"id": "f0", "type": "textarea", "label": "Every document or login I need, and where each one is right now:"}, {"id": "f1", "type": "textarea", "label": "The ones I have to ask someone else for, and when I will ask:"}, {"id": "f2", "type": "textarea", "label": "My sittings: day, start time, stop time, for each of the next two weeks:"}, {"id": "f3", "type": "textarea", "label": "What I will do when I hit a question I cannot answer:"}, {"id": "f4", "type": "textarea", "label": "The small thing I get after each sitting ends:"}, {"id": "f5", "type": "textarea", "label": "After the first sitting: how long it actually took, and what I notice:"}]'::jsonb, array['stress', 'pacing', 'planning']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('good-enough-housework-standard-sheet', 'Good Enough Housework Standard Sheet', 'worksheet'::resource_kind, 'A sheet for setting a livable standard for dishes, laundry and floors, separate from the standard the client was raised with.', 'Use it to help a client whose home shames them agree with themselves on what clean enough means this season.', array['Adults']::text[], '25 minutes', 'Many clients measure their home against a parent''s standard or an imagined visitor''s and then do nothing because the gap is too big. The sheet takes each household task, asks what the inherited standard is, what the client could actually keep up this season, and what the minimum is that keeps the home workable. The gap between inherited and workable is where the shame lives. Agree on the workable standard and treat anything above it as extra. Revisit when circumstances change; a standard set during a hard season is not a life sentence.', '[{"id": "f0", "type": "textarea", "label": "The standard for a clean home I grew up with, and whose voice it is in:"}, {"id": "f1", "type": "textarea", "label": "Dishes: the standard I inherited, and the one I could actually keep this season:"}, {"id": "f2", "type": "textarea", "label": "Laundry: the standard I inherited, and the one I could actually keep this season:"}, {"id": "f3", "type": "textarea", "label": "Floors and surfaces: the standard I inherited, and the one I could actually keep:"}, {"id": "f4", "type": "textarea", "label": "What I say to myself when the home is below the inherited standard:"}, {"id": "f5", "type": "textarea", "label": "My good enough standard for this season, written as a short rule I can live with:"}]'::jsonb, array['routines', 'self-criticism', 'habits']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('sent-text-with-no-reply-thought-record', 'Sent Text With No Reply Thought Record', 'cbt'::resource_kind, 'A thought record for the hours after sending a message that has not been answered, with the mind-reading made visible.', 'Use it to help a client catch the stories they write about silence before the story becomes the fact.', array['Adults', 'Teens']::text[], '10 minutes per entry, one week', 'A sent message with no reply is one of the most frequent triggers for mind reading in people who are anxious about relationships. The record captures the message, the time waited, the automatic thought about why there is no reply, the emotion and its intensity, and three ordinary explanations for silence. Then it asks what actually happened when the reply came. Over a week most clients see a pattern: the feared explanation rarely appears. Look at how long the client waits before the thought starts; that number is useful later.', '[{"id": "f0", "type": "textarea", "label": "The message I sent, who to, and how long I have waited:"}, {"id": "f1", "type": "textarea", "label": "What my mind says the silence means:"}, {"id": "f2", "type": "textarea", "label": "How I feel believing that, and how strongly (0 to 100):"}, {"id": "f3", "type": "textarea", "label": "Three ordinary reasons a person might not have replied yet:"}, {"id": "f4", "type": "textarea", "label": "What I did while waiting (checked, re-sent, withdrew, distracted myself):"}, {"id": "f5", "type": "textarea", "label": "When the reply came, or did not: what the real reason turned out to be:"}]'::jsonb, array['thought record', 'core CBT', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('overheard-laughter-alternative-explanations-sheet', 'Overheard Laughter Alternative Explanations Sheet', 'cbt'::resource_kind, 'A sheet for the moment of hearing people laugh nearby and assuming it is about you, with alternatives generated and rated.', 'Use it to help a client loosen the automatic jump from other people''s laughter to being its target.', array['Adults', 'Teens']::text[], '15 minutes', 'Overhearing laughter and assuming it is about you is a small, frequent, corrosive event for socially anxious clients. The sheet takes one instance: where, who, what the client heard, and the automatic thought. Then it asks for at least four other things the group could have been laughing at, how likely each one is, and what the client would have to see or hear to know for sure. Finish with how believable the original thought is now. The point is not that it is never about them; it is that the mind decides without evidence.', '[{"id": "f0", "type": "textarea", "label": "Where I was, who was laughing, and exactly what I heard:"}, {"id": "f1", "type": "textarea", "label": "What I immediately assumed the laughter meant:"}, {"id": "f2", "type": "textarea", "label": "Four other things they could have been laughing about:"}, {"id": "f3", "type": "textarea", "label": "How likely each explanation is, honestly, out of 100:"}, {"id": "f4", "type": "textarea", "label": "What I would need to see or hear to know it was about me:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the first thought now, and what I will do next time I hear laughter:"}]'::jsonb, array['thinking traps', 'core CBT', 'evidence']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('sunday-night-dread-prediction-log', 'Sunday Night Dread Prediction Log', 'cbt'::resource_kind, 'A log that records the Sunday evening forecast for the week ahead and checks it against how the week actually went.', 'Use it to help a client whose weekends end in dread test the forecast against the week it predicts.', array['Adults']::text[], 'Five minutes Sunday, five minutes Friday, four weeks', 'Sunday night dread is often a vague forecast of a bad week rather than a specific worry, which makes it hard to test. The log asks for the forecast in concrete terms: what specifically will go wrong, how bad the week will be out of ten, and the one moment the client dreads most. On Friday they rate the week, note what happened at the dreaded moment, and record anything good they did not predict. Four weeks of data usually shows the forecast running darker than the week. Then the dread can be treated as a habit of Sunday evening rather than information about Monday.', '[{"id": "f0", "type": "textarea", "label": "Sunday: what specifically I expect to go wrong this week:"}, {"id": "f1", "type": "textarea", "label": "Sunday: how bad the week will be, 0 to 10, and the moment I dread most:"}, {"id": "f2", "type": "textarea", "label": "Sunday: what I did with the dread this evening:"}, {"id": "f3", "type": "textarea", "label": "Friday: how bad the week actually was, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "Friday: what happened at the moment I dreaded most:"}, {"id": "f5", "type": "textarea", "label": "Friday: anything good that happened that I did not predict:"}]'::jsonb, array['predictions', 'core CBT', 'worry']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('saying-no-makes-me-selfish-rule-test-sheet', 'Saying No Makes Me Selfish Rule Test Sheet', 'cbt'::resource_kind, 'A rule-testing sheet for the belief that declining a request makes a person selfish, with costs listed and a small test planned.', 'Use it to help a client who cannot decline anything examine the rule that runs the yes and try one no.', array['Adults', 'Teens']::text[], '30 minutes to plan, one week to test', 'Clients who say yes to everything usually hold a rule they have never said out loud: a good person does not refuse. The sheet gets the rule written in the client''s words, lists what following it costs and what it protects them from, and asks how they judge other people who say no. Then it plans one small refusal this week, with the prediction of what will happen and how the person will react. Review the outcome against the prediction. Clients often learn the other person barely noticed, which is harder on the rule than any argument.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my words: if I say no then..."}, {"id": "f1", "type": "textarea", "label": "What following this rule costs me in a typical week:"}, {"id": "f2", "type": "textarea", "label": "What the rule protects me from, or what I fear would happen without it:"}, {"id": "f3", "type": "textarea", "label": "How I judge a friend who says no to me; is the rule the same for them?"}, {"id": "f4", "type": "textarea", "label": "One small request I will decline this week, and the exact words I will use:"}, {"id": "f5", "type": "textarea", "label": "My prediction of how they will react, and after: what actually happened:"}]'::jsonb, array['core beliefs', 'assertiveness', 'behavioral experiment']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('tired-or-sad-body-cue-attribution-sheet', 'Tired or Sad Body Cue Attribution Sheet', 'cbt'::resource_kind, 'A sheet for sorting heavy, slow or foggy body sensations by what else could explain them before the mind calls them sadness.', 'Use it to help a client notice when they read tiredness, hunger or illness as proof their mood has collapsed.', array['Adults', 'Teens']::text[], '10 minutes per entry, one week', 'Heaviness, fog and slowness are read by many clients as evidence that the low mood is back, when sleep, a long day, a cold or dehydration would explain them just as well. The sheet logs the sensation, the mood conclusion the mind drew, and then runs through the alternatives: hours slept, when they last ate or drank, physical exertion, illness, time of day. Then the client rates how much the sensation still means mood. The goal is not to deny low mood but to stop the body''s ordinary signals from being counted as relapse.', '[{"id": "f0", "type": "textarea", "label": "The sensation I noticed (heavy, foggy, slow, flat) and when:"}, {"id": "f1", "type": "textarea", "label": "What my mind concluded it meant about my mood:"}, {"id": "f2", "type": "textarea", "label": "Hours I slept last night, and when I last ate and drank:"}, {"id": "f3", "type": "textarea", "label": "What my body did today, and whether I might be getting sick:"}, {"id": "f4", "type": "textarea", "label": "Knowing all that, how much the sensation is about mood (0 to 100):"}, {"id": "f5", "type": "textarea", "label": "What I will do for the body first, and when I will check the mood again:"}]'::jsonb, array['core CBT', 'thinking traps', 'body awareness']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('dead-persons-goals-rewrite-page', 'Dead Person''s Goals Rewrite Page', 'act'::resource_kind, 'A page that catches goals a dead person could meet, like never feeling anxious, and rewrites each as something only the living can do.', 'Use it to help a client turn goals about not feeling things into goals about doing things.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients arrive with goals that a corpse could meet perfectly: stop worrying, never lose my temper, not feel sad. The page lists the client''s goals and asks of each whether a dead person could do it better. Every yes gets rewritten into what the client would be doing, with whom, if the feeling were no longer running the show. The humor helps; keep it light. Watch for rewrites that smuggle the feeling back in (be calm at the party); push for observable action (stay at the party for an hour and talk to two people).', '[{"id": "f0", "type": "textarea", "label": "The goals I have for therapy or for my life right now, as I would normally say them:"}, {"id": "f1", "type": "textarea", "label": "For each one: could a dead person do this better than me? Mark the yeses."}, {"id": "f2", "type": "textarea", "label": "Rewrite each yes: if the feeling were not in charge, I would be doing..."}, {"id": "f3", "type": "textarea", "label": "Who would notice the difference, and what would they see me doing?"}, {"id": "f4", "type": "textarea", "label": "The first rewritten goal I will act on this week, and the smallest version of it:"}]'::jsonb, array['core ACT', 'committed action', 'values']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('holding-the-beach-ball-under-water-page', 'Holding the Beach Ball Under Water Page', 'act'::resource_kind, 'A metaphor page comparing pushing feelings down to holding a beach ball under water, and what happens when the hands let go.', 'Use it to help a client see the cost of suppressing a feeling and try letting it float.', array['Adults', 'Teens']::text[], '20 minutes', 'Holding a beach ball under water takes constant effort, both hands, and it pops up anyway the moment attention slips. The page asks the client which feeling they are holding under, what the holding costs them in a day (energy, attention, things not done), and when the ball last popped up. Then it describes letting the ball float beside them: it is there, it is wet, it bobs, and the hands are free. Try it in session with a current small feeling. Clients often notice the feeling is less frightening afloat than it was under the hands.', '[{"id": "f0", "type": "textarea", "label": "The feeling I keep pushing down, and how I push it (busyness, scrolling, snapping, numbing):"}, {"id": "f1", "type": "textarea", "label": "What the holding costs me in a day: energy, attention, things I did not do:"}, {"id": "f2", "type": "textarea", "label": "The last time the ball popped up anyway: what happened?"}, {"id": "f3", "type": "textarea", "label": "In session, letting it float: what I noticed in my body and my hands:"}, {"id": "f4", "type": "textarea", "label": "Where I will practice letting it float this week, and for how long:"}]'::jsonb, array['core ACT', 'acceptance', 'metaphor']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('clean-versus-dirty-discomfort-sorting-page', 'Clean Versus Dirty Discomfort Sorting Page', 'act'::resource_kind, 'A sorting page that separates the discomfort life delivers from the extra discomfort added by fighting it.', 'Use it to help a client see how much of their suffering is the struggle rather than the original pain.', array['Adults', 'Teens']::text[], '25 minutes', 'Clean discomfort is the pain that comes with being alive: grief, rejection, frightening news about a relative, a boring job. Dirty discomfort is what gets added by fighting the first kind: the shame about the grief, the anger at being anxious, the rumination about the rumination. The page takes a current hard situation and sorts the client''s experience into the two columns. Then it asks what would be left if the second column emptied. Most clients see the second column is the longer one and that it is the one they have a say in.', '[{"id": "f0", "type": "textarea", "label": "The situation that hurts right now, in a sentence:"}, {"id": "f1", "type": "textarea", "label": "Clean discomfort: the pain that comes directly from the situation itself:"}, {"id": "f2", "type": "textarea", "label": "Dirty discomfort: what I add by fighting, judging or avoiding the first kind:"}, {"id": "f3", "type": "textarea", "label": "Which column is longer, and which one I spend more hours in:"}, {"id": "f4", "type": "textarea", "label": "If the second column emptied, what would be left to carry, and what could I do while carrying it?"}]'::jsonb, array['core ACT', 'acceptance', 'willingness']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('why-does-that-matter-values-ladder-page', 'Why Does That Matter Values Ladder Page', 'act'::resource_kind, 'A ladder page that asks why does that matter of a goal five times, until it reaches the value under it.', 'Use it to help a client find the value beneath a goal they feel flat about so the goal can be remade or dropped.', array['Adults', 'Teens']::text[], '20 minutes', 'A goal that a client cannot get moving on is often several rungs away from anything they care about. The page starts with the goal, asks why that matters, writes the answer, and asks again, down five rungs. The bottom rung is usually a value in plain words: being someone my kids can rely on, learning, making things. Then the client looks back up the ladder and decides whether the original goal is the best way to serve the value or whether another action would serve it better. Sometimes the goal turns out to be someone else''s and gets dropped; that is also a result.', '[{"id": "f0", "type": "textarea", "label": "The goal I am stuck on, as I usually say it:"}, {"id": "f1", "type": "textarea", "label": "Why does that matter? First answer:"}, {"id": "f2", "type": "textarea", "label": "Why does that matter? Second answer:"}, {"id": "f3", "type": "textarea", "label": "Why does that matter? Third answer:"}, {"id": "f4", "type": "textarea", "label": "Why does that matter? Fourth and fifth answers, until it is about who I want to be:"}, {"id": "f5", "type": "textarea", "label": "Looking back up the ladder: is the original goal the best way to live that value, or is there a better one?"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('the-minds-job-is-to-warn-not-to-decide-page', 'The Mind''s Job Is to Warn Not to Decide Page', 'act'::resource_kind, 'A page that gives the mind its proper job, warning, and takes back the job of deciding, with a week of warnings logged.', 'Use it to help a client thank the mind for a warning and still choose what they do next.', array['Adults', 'Teens']::text[], '15 minutes to set up, one week of entries', 'Minds are warning machines and they are good at it; the trouble starts when a warning is treated as a decision. The page sets the division of labor out plainly: the mind''s job is to point at what could go wrong, the client''s job is to decide what to do about it. The log then records each warning this week, what the mind said, whether the client let the warning decide, and what they chose when they chose for themselves. Expect the mind to issue the same warning after the choice is made. That is it doing its job, not a sign the choice was wrong.', '[{"id": "f0", "type": "textarea", "label": "A warning my mind gives me often, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "What the warning is trying to protect me from:"}, {"id": "f2", "type": "textarea", "label": "This week, each time it came: did I let the warning decide, or did I decide?"}, {"id": "f3", "type": "textarea", "label": "A time this week I thanked the mind and chose anyway: what I did:"}, {"id": "f4", "type": "textarea", "label": "What the mind said after I chose, and what I did with that:"}]'::jsonb, array['core ACT', 'defusion', 'committed action']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('check-the-facts-for-jealousy-sheet', 'Check the Facts for Jealousy Sheet', 'dbt'::resource_kind, 'A Check the Facts sheet for a jealous surge, separating what was seen from what was assumed and testing whether the emotion fits the facts.', 'Use it to help a client slow a jealous reaction to the facts before it becomes an accusation.', array['Adults', 'Teens']::text[], '20 minutes', 'Jealousy fits the facts when something the client values in a relationship is actually at risk of being taken; it does not fit when the threat is assumed. The sheet records the prompting event exactly as observed, the interpretation, the emotion and its intensity, and then asks what else could be true and what the actual threat is. If the facts support the jealousy, the client moves to problem solving; if not, opposite action (staying warm, not checking, not interrogating) is the next step. Run it on a recent event in session; clients find the observed column is very short.', '[{"id": "f0", "type": "textarea", "label": "What I actually saw or heard, with no interpretation added:"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant:"}, {"id": "f2", "type": "textarea", "label": "The emotion and its intensity, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What else could explain what I saw?"}, {"id": "f4", "type": "textarea", "label": "Is something I value actually being threatened? What is the evidence either way?"}, {"id": "f5", "type": "textarea", "label": "If the jealousy fits the facts, my problem-solving step; if it does not, my opposite action:"}]'::jsonb, array['check the facts', 'core DBT', 'emotion regulation']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('dear-man-for-the-stranger-who-cut-the-line-sheet', 'DEAR MAN for the Stranger Who Cut the Line Sheet', 'dbt'::resource_kind, 'A DEAR MAN script sheet for a small public situation with a stranger, built so the client can practice the skill where the stakes are low.', 'Use it to give a client a low-stakes rehearsal of asking for something from someone they will never see again.', array['Adults', 'Teens']::text[], '15 minutes', 'DEAR MAN is usually learned on high-stakes asks with people who matter, which is the hardest place to learn anything. This sheet uses a stranger: someone who cut the line, took the seat, or is on speakerphone in the waiting room. The client writes each letter (Describe, Express, Assert, Reinforce, stay Mindful, Appear confident, Negotiate) for the small situation and decides whether they would actually say it. Then they pick one real chance this week. The point is reps, not the line; review tone and whether they held the ask when the person pushed back.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts of what the person did, no judgment:"}, {"id": "f1", "type": "textarea", "label": "Express: how it affected me, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Assert: what I am asking for, in plain words:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: why it works for them to say yes, or a simple thank you:"}, {"id": "f4", "type": "textarea", "label": "Mindful and Appear confident: what I will do if they argue or ignore me (my broken record line, my posture):"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I would settle for; and after the real try this week, what happened:"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-guilt-that-does-not-fit-the-facts-card', 'Opposite Action for Guilt That Does Not Fit the Facts Card', 'dbt'::resource_kind, 'A card for guilt that does not fit the facts: no value was broken, so the action is to keep doing the thing and let the guilt ride along.', 'Use it to help a client stop apologizing and undoing when their guilt does not point at anything they did wrong.', array['Adults', 'Teens']::text[], '10 minutes to build, use as needed', 'Guilt fits the facts when the client has acted against their own values; often it does not, as when they rested, said no, or spent money on themselves. For guilt that does not fit, the DBT move is opposite action: do the thing again, do it in the open, do not apologize or make it up to anyone, and adopt a posture that does not look guilty. The card has the client name a recurring guilt, check it against their actual values, and plan the opposite action with the body included. Watch for apologizing anyway at the end; that is the guilt getting the last word.', '[{"id": "f0", "type": "textarea", "label": "The thing I feel guilty about that I keep doing anyway (resting, saying no, buying, leaving early):"}, {"id": "f1", "type": "textarea", "label": "Which of my values did it break? If none, write none:"}, {"id": "f2", "type": "textarea", "label": "What the guilt makes me do: apologize, explain, make it up, hide it:"}, {"id": "f3", "type": "textarea", "label": "My opposite action: I will do it again, openly, without apologizing, by..."}, {"id": "f4", "type": "textarea", "label": "My body during the opposite action: posture, voice, where I look:"}, {"id": "f5", "type": "textarea", "label": "After: how the guilt changed over the week of doing the opposite:"}]'::jsonb, array['opposite action', 'guilt', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('self-soothe-menu-for-a-hotel-room-away-from-home-card', 'Self-Soothe Menu for a Hotel Room Away From Home Card', 'dbt'::resource_kind, 'A five-senses self-soothe menu built from what fits in a suitcase and what a hotel room already has.', 'Use it to help a client who falls apart on work trips plan soothing that travels.', array['Adults']::text[], '15 minutes', 'Clients who manage fine at home often lose every skill in a hotel room: the kit is at home, the routine is gone, and the minibar is right there. The card builds a self-soothe menu by sense from two sources, what goes in the suitcase (a scent, a photo, a familiar tea bag, a soft shirt) and what the room already has (the bath, the window, the heavy curtains, the ice machine). Include a plan for the first ten minutes after check-in, when the loneliness usually lands. Review after the next trip and swap what did not travel well.', '[{"id": "f0", "type": "textarea", "label": "Sight: what I will pack and what the room will have:"}, {"id": "f1", "type": "textarea", "label": "Sound: what I will listen to, and how (headphones, phone speaker, the bath running):"}, {"id": "f2", "type": "textarea", "label": "Smell and taste: what fits in my bag:"}, {"id": "f3", "type": "textarea", "label": "Touch: what I will pack, and what the room offers (bath, blankets, a walk):"}, {"id": "f4", "type": "textarea", "label": "My first ten minutes after check-in, step by step:"}, {"id": "f5", "type": "textarea", "label": "After the trip: what traveled well and what I will change:"}]'::jsonb, array['self-soothing', 'core DBT', 'distress tolerance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('wise-mind-for-a-job-offer-decision-sheet', 'Wise Mind for a Job Offer Decision Sheet', 'dbt'::resource_kind, 'A wise mind sheet for a job offer: the emotion mind pull, the reasonable mind list, and the quiet answer under both.', 'Use it to help a client make a job decision that is neither a panic yes nor a spreadsheet no.', array['Adults']::text[], '30 minutes', 'A job offer puts emotion mind (flattery, fear of the current job, dread of change) and reasonable mind (salary, commute, title) in a loud argument, and the client often picks whichever is louder on the day. The sheet gives each mind its say in full, then asks the client to settle, breathe, and write what they know underneath both. Ask them to notice where in the body the wise mind answer sits and whether it stays steady over three days. A decision that keeps changing with the mood is not from wise mind yet; give it time.', '[{"id": "f0", "type": "textarea", "label": "Emotion mind: everything I feel about the offer, including the parts I would not say out loud:"}, {"id": "f1", "type": "textarea", "label": "Reasonable mind: the facts, numbers and logistics, for and against:"}, {"id": "f2", "type": "textarea", "label": "What I notice emotion mind is afraid of, and what reasonable mind is leaving out:"}, {"id": "f3", "type": "textarea", "label": "After settling for a few minutes: what I know underneath both voices:"}, {"id": "f4", "type": "textarea", "label": "Where in my body that answer sits, and whether it is steady over three days:"}, {"id": "f5", "type": "textarea", "label": "My decision, and the first thing I will do about it:"}]'::jsonb, array['wise mind', 'decisions', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('long-distance-call-rituals-planner-for-partners', 'Long Distance Call Rituals Planner for Partners', 'couples'::resource_kind, 'A planner for partners living apart that sets the daily and weekly call rituals, with each partner naming what they need from a call.', 'Use it to help a long-distance couple replace guilt-driven check-ins with calls that both of them look forward to.', array['Couples']::text[], '45 minutes', 'Long-distance couples often drift into calls that are obligation on one side and interruption on the other. The planner has each partner describe, separately first, what a good call does for them (hearing about the day, seeing the face, silence while both work, planning the next visit) and what a bad call does. Then together they set a short daily touchpoint, one longer weekly call with a shape, and the rules for a call that is not working (how to end it kindly). Watch for the partner who needs more contact feeling ashamed of it; need is data, not a flaw.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what a good call gives me, and what a bad call feels like:"}, {"id": "f1", "type": "textarea", "label": "Partner two: what a good call gives me, and what a bad call feels like:"}, {"id": "f2", "type": "textarea", "label": "Our daily touchpoint: when, how long, and what it is for:"}, {"id": "f3", "type": "textarea", "label": "Our weekly longer call: when, and the rough shape it will have:"}, {"id": "f4", "type": "textarea", "label": "How either of us can end a call that is not working, kindly:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: which rituals held, and what we want to adjust:"}]'::jsonb, array['couples', 'connection', 'rituals']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('laundry-folded-wrong-standards-talk-sheet-for-partners', 'Laundry Folded Wrong Standards Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for the small daily friction over how a chore gets done, with each partner''s standard named and the ownership question settled.', 'Use it to help a couple stop refighting a chore and decide who owns it and to whose standard.', array['Couples']::text[], '30 minutes', 'The fight is rarely about the towels. One partner does a task and the other redoes it, or corrects it, and both feel disrespected. The sheet names one recurring chore, has each partner describe the standard they learned and why it matters to them, and then settles the question most couples never ask out loud: who owns this task, and does the owner get to choose the standard? If both want a say, they design a standard together and the one who cares more about the detail does the detail. Review in a month; ownership drift is normal.', '[{"id": "f0", "type": "textarea", "label": "The chore, and what the friction sounds like when it happens:"}, {"id": "f1", "type": "textarea", "label": "Partner one: the standard I learned for this, and why it matters to me:"}, {"id": "f2", "type": "textarea", "label": "Partner two: the standard I learned for this, and why it matters to me:"}, {"id": "f3", "type": "textarea", "label": "Who will own this chore, and does the owner set the standard?"}, {"id": "f4", "type": "textarea", "label": "If we share it: our standard, written out, and who handles the detail that only one of us cares about:"}, {"id": "f5", "type": "textarea", "label": "After a month: has the friction dropped, and what drifted?"}]'::jsonb, array['couples', 'fairness', 'conflict']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('thermostat-and-lights-small-friction-agreement-for-partners', 'Thermostat and Lights Small Friction Agreement for Partners', 'couples'::resource_kind, 'An agreement for the small sensory frictions of sharing a home, with each partner''s comfort range and a rule for the overlap.', 'Use it to help a couple settle the daily temperature, lighting and noise skirmishes that drain goodwill.', array['Couples']::text[], '30 minutes', 'Thermostat wars, lights left on, the volume of the television: small frictions that recur ten times a day and are almost never discussed as a system. The agreement has each partner name their comfort range for temperature, light and sound, and what happens in their body when it is outside the range. Then they find the overlap and set rules for the gap: a blanket and a sweater before the dial moves, a lamp instead of the ceiling light, headphones after a certain hour. Keep it practical; the point is to take the daily fights off the table so bigger ones get the energy.', '[{"id": "f0", "type": "textarea", "label": "Partner one: my comfort ranges for temperature, light and sound, and how I feel outside them:"}, {"id": "f1", "type": "textarea", "label": "Partner two: my comfort ranges for temperature, light and sound, and how I feel outside them:"}, {"id": "f2", "type": "textarea", "label": "Where our ranges overlap, and where they do not:"}, {"id": "f3", "type": "textarea", "label": "Our rules for temperature when we disagree:"}, {"id": "f4", "type": "textarea", "label": "Our rules for lights and sound, including hours:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: which skirmishes stopped, and which still happen?"}]'::jsonb, array['couples', 'conflict', 'repair']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('sick-day-care-preferences-sheet-for-partners', 'Sick Day Care Preferences Sheet for Partners', 'couples'::resource_kind, 'A sheet where each partner describes how they want to be cared for when ill, so the other can stop guessing and get it right.', 'Use it to help a couple whose care misfires when one of them is sick learn what the other actually wants.', array['Couples']::text[], '25 minutes', 'One partner wants soup and company when sick; the other wants the door shut and no questions. Each gives what they would want and feels unappreciated when it does not land. The sheet has each partner describe their sick-day self: what helps, what feels like fussing, what they will never ask for but want, and how they want to be checked on. Then they swap and read each other''s aloud. It is a small exercise with a long reach; care that fits is one of the clearest signs a couple is paying attention.', '[{"id": "f0", "type": "textarea", "label": "Partner one: when I am sick I want you to..."}, {"id": "f1", "type": "textarea", "label": "Partner one: what feels like fussing or intrusion, and what I will not ask for but secretly want:"}, {"id": "f2", "type": "textarea", "label": "Partner two: when I am sick I want you to..."}, {"id": "f3", "type": "textarea", "label": "Partner two: what feels like fussing or intrusion, and what I will not ask for but secretly want:"}, {"id": "f4", "type": "textarea", "label": "How each of us wants to be checked on, and how often:"}, {"id": "f5", "type": "textarea", "label": "After the next sick day: what landed, and what we still got wrong:"}]'::jsonb, array['couples', 'support', 'needs']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('two-traditions-one-holiday-table-sheet-for-partners', 'Two Traditions One Holiday Table Sheet for Partners', 'couples'::resource_kind, 'A planning sheet for partners from different faith or family traditions deciding how a holiday season will look in their home.', 'Use it to help a couple build a holiday that honors both backgrounds instead of one partner quietly giving theirs up.', array['Couples']::text[], '45 minutes', 'When partners come from different traditions, one set of holidays often wins by default, and the partner whose traditions faded may not notice their resentment until years in. The sheet has each partner list the holidays and rituals they grew up with, which ones still carry meaning, and which they could let go of without loss. Then together they decide what their household will keep, blend, alternate or create new. Watch for a partner who says none of it matters to me too quickly; ask what their childhood table looked like.', '[{"id": "f0", "type": "textarea", "label": "Partner one: the holidays and rituals I grew up with, and which still carry meaning for me:"}, {"id": "f1", "type": "textarea", "label": "Partner two: the holidays and rituals I grew up with, and which still carry meaning for me:"}, {"id": "f2", "type": "textarea", "label": "Which of these each of us could let go of without a sense of loss:"}, {"id": "f3", "type": "textarea", "label": "What our household will keep from each tradition, and what we will blend:"}, {"id": "f4", "type": "textarea", "label": "What we will alternate between years, and anything new we want to create together:"}, {"id": "f5", "type": "textarea", "label": "How we will explain our choices to each family, and who speaks to whom:"}]'::jsonb, array['couples', 'family', 'values']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('monster-spray-bedtime-bottle-craft', 'Monster Spray Bedtime Bottle Craft', 'kids'::resource_kind, 'A craft where the child decorates a spray bottle of water as monster spray and the parent uses it in the bedtime routine.', 'Use it to give a child with bedtime fears a tool they made and the parent a way to join them in being brave.', array['Children']::text[], '30 minutes to make, used nightly', 'A child who fears monsters at bedtime does better with a ritual they control than with an argument about whether monsters exist. The child decorates a small spray bottle of water with stickers and a label (their words: Monster Spray, Brave Mist), and chooses the spots in the room to spray each night. The parent''s job is to take it seriously, spray where asked, and then move on to the ordinary routine without lingering on the fear. Coach the parent not to add new spots or extend the ritual; two or three sprays and done. Fade it as the fear fades.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe what the spray bottle will look like and what it will be called:"}, {"id": "f1", "type": "textarea", "label": "The spots in my room that get sprayed each night:"}, {"id": "f2", "type": "textarea", "label": "Who sprays, and how many sprays each spot gets:"}, {"id": "f3", "type": "textarea", "label": "What I do right after spraying (into bed, book, lights):"}, {"id": "f4", "type": "textarea", "label": "Parent: what I will say if my child asks for more spots or more sprays:"}]'::jsonb, array['children', 'craft', 'sleep']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('sock-puppet-feelings-talk-show', 'Sock Puppet Feelings Talk Show', 'kids'::resource_kind, 'A play activity where sock puppets host a talk show about feelings, with the parent as the audience and sometimes a guest.', 'Use it to let a child say things through a puppet that they will not yet say as themselves.', array['Children']::text[], '30 minutes', 'Children often tell a puppet what they cannot tell a person. Child and parent make two sock puppets, a host and a guest, and the host interviews the guest about a feeling: when it visits, what it feels like, what helps. The parent sits in the audience and claps, and may be invited on as a guest to answer the same questions about a feeling of their own. Let the child run the show. Coach the parent to resist correcting or asking the puppet follow-up questions about real events; the point is that the puppet is safe.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe my two puppets and their names:"}, {"id": "f1", "type": "textarea", "label": "The feeling our show is about today:"}, {"id": "f2", "type": "textarea", "label": "Host questions: when does this feeling visit you, and what does it feel like inside?"}, {"id": "f3", "type": "textarea", "label": "Host question: what helps when this feeling is here?"}, {"id": "f4", "type": "textarea", "label": "Parent as guest: a feeling I will talk about, and what helps me:"}, {"id": "f5", "type": "textarea", "label": "What the audience learned from today''s show:"}]'::jsonb, array['children', 'play', 'emotion identification']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('gratitude-tree-paper-leaves-craft', 'Gratitude Tree Paper Leaves Craft', 'kids'::resource_kind, 'A craft where the family grows a paper tree on the wall, adding a leaf for something each person was glad of that day.', 'Use it to give a family a daily, visible way to notice good things together without it becoming a chore.', array['Children']::text[], '30 minutes to make, a minute a day', 'A paper trunk goes on the wall and a stack of cut-out leaves beside it. Each evening, anyone who wants to writes or draws one thing they were glad of and sticks it on. The parent adds their own leaf every night and never requires one from the child; a tree that is a chore dies fast. Over weeks the tree fills and the child can read it back on a hard day. Watch for a parent who turns the leaves into lessons (see, you have so much to be grateful for); the tree works by noticing, not by arguing with bad moods.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe our tree: where it will go and what the leaves will look like:"}, {"id": "f1", "type": "textarea", "label": "My first leaf: something I was glad of today:"}, {"id": "f2", "type": "textarea", "label": "Parent: my first leaf, something I was glad of today:"}, {"id": "f3", "type": "textarea", "label": "When each day we will add leaves:"}, {"id": "f4", "type": "textarea", "label": "What we will do with the tree when it is full:"}]'::jsonb, array['children', 'craft', 'gratitude']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('calm-kit-lunchbox-pack-activity', 'Calm Kit Lunchbox Pack Activity', 'kids'::resource_kind, 'An activity where the child packs an old lunchbox with small things that help them settle, and the parent helps decide where it lives.', 'Use it to help a child build a portable calm kit they chose and know how to open before a meltdown rather than during one.', array['Children']::text[], '40 minutes', 'The child and parent gather candidates: something to squeeze, something to smell, a small photo, a card with a breathing picture, a tiny toy, headphones. The child tests each one and keeps what actually helps. The kit goes in an old lunchbox the child decorates, and parent and child agree where it lives at home and whether a smaller version goes in the backpack. Practice opening it on a calm day. Coach the parent to offer the kit early (I see your fists are tight, want your lunchbox?) and never as a punishment or time-out.', '[{"id": "f0", "type": "textarea", "label": "Draw or list everything that went in my lunchbox and why:"}, {"id": "f1", "type": "textarea", "label": "Things I tried that did not help, and why I left them out:"}, {"id": "f2", "type": "textarea", "label": "Where my lunchbox lives at home, and what goes in my backpack version:"}, {"id": "f3", "type": "textarea", "label": "The sign my body gives that it is time to open it:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I will offer the kit early, and what I will say:"}]'::jsonb, array['children', 'self-soothing', 'craft']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('lion-breath-and-mouse-breath-play', 'Lion Breath and Mouse Breath Play', 'kids'::resource_kind, 'A breathing game of big loud lion exhales and tiny quiet mouse breaths that the parent leads and the child soon leads back.', 'Use it to teach a young child that breath can be loud or quiet and that they can pick which one their body needs.', array['Children']::text[], '10 minutes, repeatable', 'Lion breath is a huge inhale through the nose and a loud open-mouth roar out with the tongue stuck out; mouse breath is a tiny sniff in and the smallest, quietest exhale through pursed lips. The parent leads three of each, then asks the child to be the leader and call them. Lion breath is for when the body is full of a big feeling that needs to come out; mouse breath is for settling. Play it on calm days until the child can call for mouse breaths when they notice they need them. Coach the parent to play it, not teach it.', '[{"id": "f0", "type": "textarea", "label": "Draw my lion and my mouse:"}, {"id": "f1", "type": "textarea", "label": "When my body needs lion breaths (what big feelings):"}, {"id": "f2", "type": "textarea", "label": "When my body needs mouse breaths:"}, {"id": "f3", "type": "textarea", "label": "Three lion breaths and three mouse breaths: what my body felt like after each:"}, {"id": "f4", "type": "textarea", "label": "Parent: a moment this week I could offer lion or mouse breaths, and how I will ask:"}]'::jsonb, array['children', 'breathing', 'play']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('back-to-back-drawing-listening-game', 'Back-to-Back Drawing Listening Game', 'game'::resource_kind, 'A pairs game where one person describes a simple picture and the other draws it without seeing it, then they compare and debrief.', 'Use it to show a group how instructions get lost between speaker and listener and what fixes it.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Pairs sit back to back. One holds a simple line drawing (a house with a sun, three shapes stacked) and describes it; the other draws from the description alone, no questions in round one. Compare. Round two swaps roles and allows questions. Round three allows the listener to repeat back before drawing. The debrief asks which round produced the closest drawing and why, and where in daily life each person is the describer who assumes and the drawer who guesses. The rule that matters: no peeking, and no blaming the drawer.', '[{"id": "f0", "type": "textarea", "label": "Round one, no questions: how close was the drawing, and what got lost?"}, {"id": "f1", "type": "textarea", "label": "Round two, questions allowed: what changed?"}, {"id": "f2", "type": "textarea", "label": "Round three, repeating back allowed: what changed?"}, {"id": "f3", "type": "textarea", "label": "Where in my life am I the describer who assumes the other person can see the picture?"}, {"id": "f4", "type": "textarea", "label": "Where am I the drawer who guesses instead of asking?"}, {"id": "f5", "type": "textarea", "label": "One thing I will do differently in a real conversation this week:"}]'::jsonb, array['game', 'communication', 'group']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('minefield-blindfold-guide-trust-game', 'Minefield Blindfold Guide Trust Game', 'game'::resource_kind, 'A pairs game where a blindfolded walker crosses a floor scattered with soft obstacles guided only by a partner''s voice.', 'Use it to let a group practice giving clear guidance and trusting it, then talk about where trust is hard.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Scatter soft objects (cushions, paper balls, rolled towels) across the floor. One partner is blindfolded at one end; the other stands at the far end and guides them across by voice only, no touching. Touching an object means starting over. Swap roles. The debrief asks the walker what made a guide easy to trust (specific words, calm tone, warning early) and the guide what it was like to be responsible for someone who could not see. Keep the obstacles soft and the room clear of hard edges; the fear should be small and the lesson real.', '[{"id": "f0", "type": "textarea", "label": "As the walker: what my guide did that made them easy to trust:"}, {"id": "f1", "type": "textarea", "label": "As the walker: the moment I wanted to lift the blindfold, and what I did:"}, {"id": "f2", "type": "textarea", "label": "As the guide: what was hard about being responsible for someone who could not see:"}, {"id": "f3", "type": "textarea", "label": "As the guide: the instruction that worked best, word for word:"}, {"id": "f4", "type": "textarea", "label": "Who in my life guides me well, and who do I guide, and how is it going?"}]'::jsonb, array['game', 'trust', 'communication']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('group-juggling-name-toss-game', 'Group Juggling Name Toss Game', 'game'::resource_kind, 'A circle game where soft balls are tossed in a fixed order with names called, adding balls until the pattern breaks.', 'Use it to warm up a group, learn names and practice staying calm when the pattern gets overloaded.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'The group stands in a circle. One ball is tossed to someone across the circle with their name called; they toss to someone new, and so on until everyone has had it once and it returns to the start. That is the pattern, and it stays fixed. Then run the pattern again and add a second ball a few seconds behind, then a third. When it collapses, everyone laughs and resets. The debrief asks what it felt like when the balls came faster than the hands, who froze and who got silly, and what helped: watching only your sender, calling names louder, slowing the pace.', '[{"id": "f0", "type": "textarea", "label": "How many balls we got to before the pattern broke:"}, {"id": "f1", "type": "textarea", "label": "What my body did when the balls came faster than I could handle:"}, {"id": "f2", "type": "textarea", "label": "What helped me most: watching my sender, slowing down, calling louder, something else?"}, {"id": "f3", "type": "textarea", "label": "Where in my week do things come at me faster than I can toss them on?"}, {"id": "f4", "type": "textarea", "label": "One trick from the game I could use there:"}]'::jsonb, array['game', 'attention', 'group']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('rose-thorn-bud-check-in-round-game', 'Rose Thorn Bud Check-In Round Game', 'game'::resource_kind, 'A check-in round where each person names a rose, a thorn and a bud, with a timer, a pass rule and a closing debrief.', 'Use it to open or close a group with a quick structured round that includes the hard thing without dwelling on it.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'Each person gets about a minute to name a rose (something good lately), a thorn (something hard) and a bud (something they are looking forward to or growing). Anyone may say pass on one of the three. The leader goes first to set the length and the honesty level. No one responds to anyone''s turn until everyone has gone; then the group may name one rose or bud they want to hear more about. The debrief is short: which of the three was hardest to find, and did anyone''s thorn sound like their own. Works with families and teens too.', '[{"id": "f0", "type": "textarea", "label": "My rose this week:"}, {"id": "f1", "type": "textarea", "label": "My thorn this week:"}, {"id": "f2", "type": "textarea", "label": "My bud: something I am looking forward to or something small that is growing:"}, {"id": "f3", "type": "textarea", "label": "Which of the three was hardest to find, and why:"}, {"id": "f4", "type": "textarea", "label": "Someone else''s rose, thorn or bud that stayed with me:"}]'::jsonb, array['game', 'group', 'feelings']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('trash-ball-unhelpful-thoughts-toss-game', 'Trash Ball Unhelpful Thoughts Toss Game', 'game'::resource_kind, 'A game where players crumple an unhelpful thought, shoot for the basket, then unfold a stranger''s and answer it back.', 'Use it to get a group handling unhelpful thoughts as objects they can pass around and talk back to.', array['Teens', 'Groups']::text[], '25 minutes', 'Each player writes one unhelpful thought they have had this week on a slip, crumples it, and takes turns shooting at a wastebasket from a line; a basket scores two, a miss scores one for trying. Then every ball is collected and redistributed, each player unfolds someone else''s thought and reads it aloud with a kinder or more accurate reply. The owner stays anonymous unless they want to claim it. Debrief: which thoughts turned up more than once, and was it easier to answer a stranger''s thought than your own. Keep the basket close so the shooting stays fun.', '[{"id": "f0", "type": "textarea", "label": "The unhelpful thought I wrote and crumpled:"}, {"id": "f1", "type": "textarea", "label": "The thought I unfolded, and the reply I gave it out loud:"}, {"id": "f2", "type": "textarea", "label": "A thought that showed up on more than one ball:"}, {"id": "f3", "type": "textarea", "label": "Was it easier to answer someone else''s thought than mine? Why?"}, {"id": "f4", "type": "textarea", "label": "The reply someone gave that I want to keep for my own thought:"}]'::jsonb, array['game', 'thinking traps', 'group']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('off-duty-hour-standing-down-plan-sheet', 'Off-Duty Hour Standing Down Plan Sheet', 'worksheet'::resource_kind, 'A plan for one hour a day when someone else is on watch and the client practices letting the guard stand down.', 'Use it to give a client who is never off duty a bounded, supported hour to practice not scanning.', array['Adults']::text[], '20 minutes to plan, one hour daily', 'Clients who live on alert after trauma rarely stop scanning because they decide to; they stop when the conditions make it briefly possible. The sheet designs an hour: who is home or reachable, which door is locked, where the client sits, what they do with their hands, and what they will say to themselves when the urge to check returns. Start with a shorter window if an hour is too long. Review what the body did in the hour and what pulled them back to scanning. This is practice at being off duty, not a test of whether they can stop.', '[{"id": "f0", "type": "textarea", "label": "The hour I will choose, and who will be on watch so I do not have to be:"}, {"id": "f1", "type": "textarea", "label": "What I will check once before the hour starts, and then not again:"}, {"id": "f2", "type": "textarea", "label": "Where I will sit and what I will do with my hands and attention:"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself when the urge to scan comes back:"}, {"id": "f4", "type": "textarea", "label": "After the first few days: what my body did in the hour, and what pulled me back to watching:"}]'::jsonb, array['PTSD and trauma', 'safety', 'pacing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('trusting-my-own-judgment-again-evidence-log', 'Trusting My Own Judgment Again Evidence Log', 'cbt'::resource_kind, 'An evidence log for a client who stopped trusting their own read on people and situations, collecting the small calls they got right.', 'Use it to help a client whose trauma taught them their judgment is broken rebuild a record of the judgment working.', array['Adults', 'Teens']::text[], 'Five minutes daily, three weeks', 'After trauma many clients conclude that their judgment failed them and cannot be trusted, and then outsource every call or freeze. The log collects small daily judgments: the client decided a stranger was fine and they were; chose a route, a time, a reply, and it worked. Each entry notes the call, the outcome, and how much the client trusted themselves beforehand. Over three weeks the record contradicts the global belief with specifics. Keep the entries ordinary; the goal is not to prove them infallible but to show the judgment is working most of the time.', '[{"id": "f0", "type": "textarea", "label": "The belief about my judgment, in my words:"}, {"id": "f1", "type": "textarea", "label": "Today''s small judgment call (about a person, a place, a plan) and what I decided:"}, {"id": "f2", "type": "textarea", "label": "How much I trusted my own read beforehand, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}, {"id": "f4", "type": "textarea", "label": "After three weeks: how many calls I got right, and how I would rewrite the belief:"}]'::jsonb, array['PTSD and trauma', 'evidence log', 'core beliefs']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('carrying-the-story-in-a-backpack-not-a-shield-page', 'Carrying the Story in a Backpack Not a Shield Page', 'act'::resource_kind, 'A metaphor page about carrying a trauma history as a backpack that can be set down, rather than a shield held in front.', 'Use it to help a client notice the difference between carrying their history and holding it up between themselves and life.', array['Adults', 'Teens']::text[], '20 minutes', 'A shield held in front keeps everything out, including people, and both arms are busy. A backpack carries the same weight but leaves the hands free and can be set down. The page asks the client where they are holding their history right now, what the shield keeps out, and what an hour would look like with the weight on their back instead. Nothing here asks what is in the pack; the contents are theirs. It is about posture toward the history, not the history. Watch for a client who hears set it down as forget it; say plainly that the pack goes with them.', '[{"id": "f0", "type": "textarea", "label": "Right now, am I holding my history up in front of me or carrying it on my back? What tells me which?"}, {"id": "f1", "type": "textarea", "label": "What the shield keeps out that I do not want kept out:"}, {"id": "f2", "type": "textarea", "label": "What my hands could do if they were not holding the shield:"}, {"id": "f3", "type": "textarea", "label": "One hour this week I will try carrying it instead, and where I will be:"}, {"id": "f4", "type": "textarea", "label": "After: what was different with the hands free, and when the shield came back up:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'metaphor']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('paced-breathing-before-walking-into-the-store-card', 'Paced Breathing Before Walking Into the Store Card', 'dbt'::resource_kind, 'A card for the parking lot pause: a minute of paced breathing and a plan before entering a crowded store.', 'Use it to give a client who dreads crowded stores a short skill at the door instead of a turnaround in the lot.', array['Adults', 'Teens']::text[], 'Five minutes per use', 'The parking lot is where the decision to turn around gets made. The card sets a routine for the car: engine off, feet flat, one minute of paced breathing with the exhale longer than the inhale, then a short plan (what I need, which aisles, where the exits are, how long I will stay). The client goes in with the list and comes out when the list is done, not when the fear says so. Keep the first trips short and the list small. Review what the body did in the lot and inside; the point is reps at the door, not a perfect trip.', '[{"id": "f0", "type": "textarea", "label": "My parking lot routine, step by step, starting with engine off:"}, {"id": "f1", "type": "textarea", "label": "Breath count that works for me (in for, out for):"}, {"id": "f2", "type": "textarea", "label": "My list for this trip and roughly how long it should take:"}, {"id": "f3", "type": "textarea", "label": "What I will do if the urge to leave comes before the list is done:"}, {"id": "f4", "type": "textarea", "label": "After: how long I was inside, and what my body did at the door and on the way out:"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'grounding']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('rough-patch-load-shift-plan-for-partners', 'Rough Patch Load Shift Plan for Partners', 'couples'::resource_kind, 'A plan for which household tasks shift to the other partner when trauma symptoms flare, and how the shift is asked for and ended.', 'Use it to help a couple handle a hard week without the struggling partner hiding it or the other partner guessing.', array['Couples']::text[], '40 minutes', 'When symptoms flare, the partner who is struggling often keeps doing everything until they cannot, and the other partner finds out by the collapse. The plan is made on a calm day: which tasks can shift (driving at night, the school run, calls), which stay no matter what, how the struggling partner signals the shift is needed, and how they signal it is over. Both partners say what they need from the other during the patch. Watch for the supporting partner taking on too much and quietly keeping score; build in a check-in halfway through.', '[{"id": "f0", "type": "textarea", "label": "Partner who struggles: the signs I am entering a rough patch, and how I will say it out loud:"}, {"id": "f1", "type": "textarea", "label": "Tasks that can shift to my partner during a patch, and tasks I want to keep:"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what I can take on for a week or two, and what I cannot:"}, {"id": "f3", "type": "textarea", "label": "What each of us needs from the other during the patch (space, company, no questions, check-ins):"}, {"id": "f4", "type": "textarea", "label": "How we signal the patch is over and the load shifts back:"}, {"id": "f5", "type": "textarea", "label": "After the next patch: what worked, and what we would change:"}]'::jsonb, array['PTSD and trauma', 'couples', 'support']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('unlistened-voicemail-avoidance-log', 'Unlistened Voicemail Avoidance Log', 'worksheet'::resource_kind, 'A log of voicemails left unplayed, how long each sat, what the client imagined it said and what it actually said.', 'Use it to help a client who cannot press play on a voicemail see the gap between the dreaded message and the real one.', array['Adults', 'Teens']::text[], 'Two weeks', 'Unplayed voicemails are a small avoidance that costs a lot: missed appointments, late fees, and a growing red badge that becomes its own dread. The log records each voicemail, how long it sat, what the client imagined it contained, the anxiety out of ten before pressing play, and what the message actually was. Most entries turn out to be routine. After the first week, add a rule: play within one hour, with the log open. Review which callers are hardest and whether the dread is about the content or about having to call back.', '[{"id": "f0", "type": "textarea", "label": "Who called, and how long the voicemail sat before I played it:"}, {"id": "f1", "type": "textarea", "label": "What I imagined the message said:"}, {"id": "f2", "type": "textarea", "label": "My anxiety before pressing play, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What the message actually said:"}, {"id": "f4", "type": "textarea", "label": "Did I have to call back, and did I? What made that part hard?"}, {"id": "f5", "type": "textarea", "label": "After two weeks: how many messages matched what I imagined?"}]'::jsonb, array['anxiety', 'avoidance', 'self-monitoring']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('arriving-forty-minutes-early-safety-behavior-experiment', 'Arriving Forty Minutes Early Safety Behavior Experiment', 'cbt'::resource_kind, 'An experiment sheet for the habit of arriving extremely early, testing what happens when the buffer is cut to something ordinary.', 'Use it to help a client who arrives everywhere far too early find out what the extra time is protecting them from.', array['Adults', 'Teens']::text[], '20 minutes to plan, one week to run', 'Arriving forty minutes early feels like being responsible, but for many anxious clients it is a safety behavior that keeps the fear of being late alive. The sheet names the current buffer, the feared outcome of cutting it, and the prediction in specifics. Then the client picks two low-stakes appointments and arrives ten minutes early, logging the anxiety on the way and what happened. Review what they did with the forty minutes before (sitting in the car rehearsing) and what they did with the recovered half hour. Do not start with the job interview.', '[{"id": "f0", "type": "textarea", "label": "How early I usually arrive, and what I do with the time:"}, {"id": "f1", "type": "textarea", "label": "What I am afraid will happen if I cut it to ten minutes:"}, {"id": "f2", "type": "textarea", "label": "My specific prediction (I will be late, I will be flustered, they will think less of me):"}, {"id": "f3", "type": "textarea", "label": "Two low-stakes appointments this week where I will arrive ten minutes early:"}, {"id": "f4", "type": "textarea", "label": "Anxiety on the way, 0 to 10, and what actually happened when I arrived:"}, {"id": "f5", "type": "textarea", "label": "What I did with the recovered time, and whether the fear came true:"}]'::jsonb, array['anxiety', 'safety behaviors', 'behavioral experiment']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('taking-anxiety-to-the-party-willingness-page', 'Taking Anxiety to the Party Willingness Page', 'act'::resource_kind, 'A willingness page for a social event where anxiety is coming too, with the client bringing it rather than waiting for it to leave.', 'Use it to help a client stop waiting to feel ready and go to the event with the anxiety riding along.', array['Adults', 'Teens']::text[], '20 minutes before, 10 minutes after', 'Many clients cancel plans because the anxiety is still there when it is time to leave, as though it needed to go first. The page reframes the event as one the anxiety is invited to: the client names the event, why it matters to them, what the anxiety will probably do in the car and at the door, and what they will be doing while it does that. A willingness rating before and after helps. Afterward they record what the anxiety did over the evening and whether their presence depended on its absence. The attendance is the win; how it felt is weather.', '[{"id": "f0", "type": "textarea", "label": "The event, when, and why going matters to me:"}, {"id": "f1", "type": "textarea", "label": "What my anxiety will probably do on the way and in the first ten minutes:"}, {"id": "f2", "type": "textarea", "label": "What I will be doing while it does that (who I will talk to, where I will stand, what I will hold):"}, {"id": "f3", "type": "textarea", "label": "My willingness to bring it along, 0 to 10, right now:"}, {"id": "f4", "type": "textarea", "label": "After: what the anxiety did over the evening, and what I did anyway:"}]'::jsonb, array['anxiety', 'willingness', 'committed action']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('cope-ahead-card-for-the-job-interview', 'Cope Ahead Card for the Job Interview', 'dbt'::resource_kind, 'A cope ahead card for an interview: the hard moments rehearsed in imagination with the skill the client will use at each one.', 'Use it to help a client walk through an interview in advance with a skill ready for the moments that scare them.', array['Adults']::text[], '25 minutes', 'Cope ahead works by rehearsing the situation vividly, including the hard moments, with the skill chosen beforehand. For an interview the hard moments are predictable: the handshake and small talk, the question they cannot answer, the pause that goes on too long, the question about why they left. The card names each moment, the emotion it will bring, and the skill (paced breathing, describe the facts, a prepared sentence, willing hands under the table). Then the client imagines it in detail, including recovering from a stumble. Rehearse the stumble; a rehearsal with no mistakes prepares no one.', '[{"id": "f0", "type": "textarea", "label": "The interview: when, where, and what I most want them to know about me:"}, {"id": "f1", "type": "textarea", "label": "Hard moment one and the skill I will use:"}, {"id": "f2", "type": "textarea", "label": "Hard moment two and the skill I will use:"}, {"id": "f3", "type": "textarea", "label": "Hard moment three (the question I cannot answer) and my recovery sentence:"}, {"id": "f4", "type": "textarea", "label": "Imagining the whole thing including a stumble: what I noticed in my body, and what I did in the rehearsal:"}, {"id": "f5", "type": "textarea", "label": "After the interview: which moment came, and did the skill show up?"}]'::jsonb, array['anxiety', 'core DBT', 'skills']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('worry-worms-flower-pot-craft', 'Worry Worms Flower Pot Craft', 'kids'::resource_kind, 'A craft where the child writes worries on paper worms and buries them in a real flower pot, then plants a seed on top with the parent.', 'Use it to give a worried child a way to put worries somewhere and watch something else grow in their place.', array['Children']::text[], '40 minutes to make, a minute a day to water', 'The child cuts paper worms, writes or draws one worry on each, and wiggles them into the soil of a flower pot. Then the parent helps them plant a fast seed, beans or grass, on top, and the child waters it each day. The worms are not gone; they are in the pot, where the child can add more when a worry comes. The parent''s job is to say we can put that one in the pot too, and to water alongside. Coach the parent not to dig the worms up to discuss them; a worry in the pot is a worry handled for now. Talk about the worries in session if they are large.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe my pot and what I planted on top:"}, {"id": "f1", "type": "textarea", "label": "The worries I put on worms today:"}, {"id": "f2", "type": "textarea", "label": "When I will water the pot each day, and who waters with me:"}, {"id": "f3", "type": "textarea", "label": "What I will do when a new worry comes: say it, write it, and..."}, {"id": "f4", "type": "textarea", "label": "Parent: the sentence I will use when my child brings a worry to the pot:"}]'::jsonb, array['anxiety', 'children', 'craft']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('fresh-air-minute-daily-log', 'Fresh Air Minute Daily Log', 'worksheet'::resource_kind, 'A log of one minute a day outside or at an open window, with the time, what the client noticed, and the mood before and after.', 'Use it to give a client who cannot face a walk a one-minute version that still counts.', array['Adults', 'Teens']::text[], 'One minute daily, two weeks', 'A walk is too much on heavy days, and a client who cannot do the walk often does nothing. The log asks for one minute a day of outside air: on the step, at an open window, in the yard, no destination. They record the time, three things they noticed with their senses, and the mood before and after out of ten. The point is a step small enough to happen every day. Review whether any minute stretched on its own. Do not push for the walk; if the minute becomes five, that came from the client.', '[{"id": "f0", "type": "textarea", "label": "Today''s minute: where I stood and what time it was:"}, {"id": "f1", "type": "textarea", "label": "Three things I noticed (a sound, a temperature, a smell, something I saw):"}, {"id": "f2", "type": "textarea", "label": "Mood before, 0 to 10, and mood after:"}, {"id": "f3", "type": "textarea", "label": "Did the minute stretch on its own? If so, to how long?"}, {"id": "f4", "type": "textarea", "label": "After two weeks: how many days I did it, and what I notice about the days I did:"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('i-have-nothing-to-say-social-prediction-sheet', 'I Have Nothing to Say Social Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the belief that a low mood leaves nothing worth saying, tested in one short contact.', 'Use it to help a client who avoids people because they feel empty test whether the conversation actually needs them to be interesting.', array['Adults', 'Teens']::text[], '20 minutes to plan, one contact to test', 'Low mood tells people they have nothing to say and that others will find them a burden, so they stop answering the phone. The sheet records the belief in detail: what will happen in the conversation, how the other person will react, how long the silence will be. Then the client plans one short, low-stakes contact: a five-minute call, a coffee with one person, a text exchange. Afterward they log what they said, what the other person did, and how the prediction held. Most clients find the other person did most of the talking and seemed glad. That is data against the belief.', '[{"id": "f0", "type": "textarea", "label": "The belief: when I am like this, in a conversation I will..."}, {"id": "f1", "type": "textarea", "label": "How I predict the other person will react:"}, {"id": "f2", "type": "textarea", "label": "One short contact I will make this week, with whom, and for how long:"}, {"id": "f3", "type": "textarea", "label": "What I actually said, roughly, and how long the silences were:"}, {"id": "f4", "type": "textarea", "label": "How the other person seemed, and anything they said afterward:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the prediction now, 0 to 100:"}]'::jsonb, array['depression', 'predictions', 'behavioral experiment']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('pointless-passenger-on-the-bus-page', 'Pointless Passenger on the Bus Page', 'act'::resource_kind, 'A page that names the passenger who says what is the point and lets the client keep driving toward one small valued stop while it talks.', 'Use it to help a client hear what is the point as a passenger''s line rather than the driver''s conclusion.', array['Adults', 'Teens']::text[], '20 minutes', 'What is the point is the passenger that gets the most clients off the bus. The page describes the passenger: what it says, when it gets loud, what it sounds like, and what the client does when it talks (sits down, cancels, scrolls). Then the client names one small valued stop for this week and plans to drive there with the passenger talking. The passenger does not have to be convinced or quiet. Afterward they log what the passenger said on the way and whether the bus arrived anyway. Keep the stop small; a shower taken and a text sent are stops.', '[{"id": "f0", "type": "textarea", "label": "What my pointless passenger says, in its exact words, and when it gets loudest:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it talks:"}, {"id": "f2", "type": "textarea", "label": "One small stop that matters to me this week, and what I will be doing when I get there:"}, {"id": "f3", "type": "textarea", "label": "What the passenger will probably say on the way:"}, {"id": "f4", "type": "textarea", "label": "After: did the bus arrive? What did the passenger say when it did?"}]'::jsonb, array['depression', 'defusion', 'values']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotion-for-numbness-card', 'Mindfulness of Current Emotion for Numbness Card', 'dbt'::resource_kind, 'A card for mindfulness of current emotion when the emotion is flatness itself, observing numbness without trying to feel more.', 'Use it to help a client who feels nothing treat the nothing as an experience to observe rather than a failure to fix.', array['Adults', 'Teens']::text[], 'Ten minutes daily', 'Numbness is an emotion state too, and clients who try to force feeling through it usually add frustration on top. The card walks through observing it: where the flatness sits in the body, its texture (heavy, blank, distant), whether it has edges, what thoughts come with it, and how it changes over ten minutes of watching without pushing. The client notes what they wanted to do to change it and did not. Watch for a client using the practice to prove they are broken; the instruction is to watch the numbness like weather, and weather moves. If feeling comes, they watch that too.', '[{"id": "f0", "type": "textarea", "label": "Where the numbness sits in my body and what it is like (heavy, blank, far away, cotton):"}, {"id": "f1", "type": "textarea", "label": "Whether it has edges, and what is just outside them:"}, {"id": "f2", "type": "textarea", "label": "Thoughts that came while I watched it:"}, {"id": "f3", "type": "textarea", "label": "What I wanted to do to change it, and did not:"}, {"id": "f4", "type": "textarea", "label": "How it was different at the end of ten minutes, if at all:"}]'::jsonb, array['depression', 'core DBT', 'mindfulness']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('good-thing-walk-scavenger-game', 'Good Thing Walk Scavenger Game', 'game'::resource_kind, 'A group walk with a card of categories to find one good thing in each, with points for finds and a debrief back inside.', 'Use it to get a group outside and noticing on a low day with rules that make looking for good things a game rather than a lecture.', array['Adults', 'Teens', 'Groups']::text[], '40 minutes', 'Each player gets a card of categories: something growing, something someone made, a kind act, a color you like, a sound you would miss, something that smells good, something that made you smile. The group walks a short route for twenty minutes and marks each category when they find it, one point each, bonus for a find no one else got. Back inside, the debrief goes round: the best find, the hardest category, and whether looking changed what they saw. Pairs work for players who struggle alone. The rule that matters: nobody has to feel better; they just have to look.', '[{"id": "f0", "type": "textarea", "label": "Categories I found, and what the finds were:"}, {"id": "f1", "type": "textarea", "label": "My best find, and why it was the best:"}, {"id": "f2", "type": "textarea", "label": "The hardest category and what I eventually found for it:"}, {"id": "f3", "type": "textarea", "label": "Did looking for good things change what I noticed on the walk? How?"}, {"id": "f4", "type": "textarea", "label": "A category I would add to the card next time:"}]'::jsonb, array['depression', 'game', 'behavioral activation']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('missed-appointment-prevention-plan-sheet', 'Missed Appointment Prevention Plan Sheet', 'worksheet'::resource_kind, 'A plan built from the client''s last three missed appointments, with the point of failure for each and one fix per point.', 'Use it to help a client who keeps missing appointments find out exactly where each one got lost and plug that hole.', array['Adults', 'Teens']::text[], '25 minutes', 'Missed appointments usually fail at the same two or three points: never entered, entered with no alert, alert dismissed while doing something else, or remembered too late to make it in time. The sheet takes the last three misses and traces each one to its failure point, then designs one fix per point: entering it before hanging up the phone, a two-alert rule, a travel-time alert, a visual calendar by the door. Keep the number of fixes small. Review after a month what the new misses have in common; the plan updates, it does not finish.', '[{"id": "f0", "type": "textarea", "label": "My last three missed appointments and how each was lost (never entered, no alert, alert dismissed, remembered too late):"}, {"id": "f1", "type": "textarea", "label": "The failure point that showed up most:"}, {"id": "f2", "type": "textarea", "label": "My fix for entering: when and where I will put an appointment in, every time:"}, {"id": "f3", "type": "textarea", "label": "My fix for alerts: how many, how far ahead, and where the travel-time alert goes:"}, {"id": "f4", "type": "textarea", "label": "My fix for the morning of: what I will see when I wake up:"}, {"id": "f5", "type": "textarea", "label": "After a month: any new misses, and what they had in common:"}]'::jsonb, array['ADHD', 'planning', 'routines']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('everyone-else-finds-this-easy-comparison-check-sheet', 'Everyone Else Finds This Easy Comparison Check Sheet', 'cbt'::resource_kind, 'A check sheet for the thought that everyone else manages the thing effortlessly, with the evidence for what other people actually do.', 'Use it to help a client separate how hard a task is for them from the story that nobody else struggles.', array['Adults', 'Teens']::text[], '15 minutes', 'The thought that everyone else finds this easy adds shame to a task that is already hard. The sheet takes one task, records the thought and how much it is believed, and then asks for evidence: who the client has actually watched do it, what they know about those people''s systems and help, and whether they have ever asked anyone how they manage. Then it separates the two claims: this is hard for me, and nobody else struggles. The first is often true and useful; the second is almost always a guess. The rewrite keeps the first and drops the second.', '[{"id": "f0", "type": "textarea", "label": "The task, and the thought about everyone else, in my words:"}, {"id": "f1", "type": "textarea", "label": "How much I believe it, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "People I have actually watched do this task, and what I know about how they do it (systems, help, time):"}, {"id": "f3", "type": "textarea", "label": "Have I ever asked anyone how they manage it? What did they say?"}, {"id": "f4", "type": "textarea", "label": "The two claims separated: how hard it is for me, and what I actually know about others:"}, {"id": "f5", "type": "textarea", "label": "My rewrite, keeping what is true and dropping what is a guess:"}]'::jsonb, array['ADHD', 'thinking traps', 'thought record']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('i-am-not-my-to-do-list-self-as-context-page', 'I Am Not My To-Do List Self-as-Context Page', 'act'::resource_kind, 'A self-as-context page for a client whose sense of self rises and falls with the day''s completed tasks.', 'Use it to help a client find the part of them that watched both the productive days and the lost ones and was the same throughout.', array['Adults', 'Teens']::text[], '20 minutes', 'When the list is done the client is a good person and when it is not they are a failure; the self has become a scoreboard. The page asks the client to recall a day the list was crushed and a day nothing got done, and to notice who was there watching both. Then it asks what that watcher cares about that is not on any list, and what it would say to the person staring at the undone items. This is not an argument for doing less; it moves the self off the scoreboard so that the list can be a tool again. Watch for the client turning the watcher into another judge.', '[{"id": "f0", "type": "textarea", "label": "A day I finished everything: what I told myself about who I was:"}, {"id": "f1", "type": "textarea", "label": "A day I finished nothing: what I told myself about who I was:"}, {"id": "f2", "type": "textarea", "label": "Who was there noticing on both days? What was the same about that part of me?"}, {"id": "f3", "type": "textarea", "label": "What that noticing part cares about that is not on any list:"}, {"id": "f4", "type": "textarea", "label": "What it would say to me when I am staring at the undone items tonight:"}]'::jsonb, array['ADHD', 'self-as-context', 'values']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('stop-skill-before-hitting-send-card', 'STOP Skill Before Hitting Send Card', 'dbt'::resource_kind, 'A STOP skill card for the impulsive message: Stop, Take a step back, Observe, Proceed mindfully, applied in the seconds before send.', 'Use it to give a client who fires off messages they regret a pause that fits between typing and sending.', array['Adults', 'Teens']::text[], 'Two minutes per use', 'The message is typed and the thumb is over send; the card goes between. Stop: hands off the phone. Take a step back: put it down, one slow breath, or walk to the other room. Observe: what is the emotion, how strong, what does the message want to achieve, what will it achieve. Proceed mindfully: send, edit, save as draft for an hour, or delete. The card has the client write the version of each step they will actually do, and log the drafts that got an hour. Review which messages were sent after the hour unchanged; those were fine. The ones edited or deleted are the win.', '[{"id": "f0", "type": "textarea", "label": "Stop: what hands off the phone looks like for me:"}, {"id": "f1", "type": "textarea", "label": "Take a step back: what I will do for one breath or one minute:"}, {"id": "f2", "type": "textarea", "label": "Observe: the questions I will ask myself (what I feel, what I want the message to do, what it will actually do):"}, {"id": "f3", "type": "textarea", "label": "Proceed mindfully: my options (send, edit, draft for an hour, delete) and my default when unsure:"}, {"id": "f4", "type": "textarea", "label": "This week: messages that got the pause, and what happened to each:"}]'::jsonb, array['ADHD', 'core DBT', 'skills']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('interrupting-mid-sentence-repair-signal-for-partners', 'Interrupting Mid-Sentence Repair Signal for Partners', 'couples'::resource_kind, 'A signal agreement for a couple where one partner interrupts, with a gesture that pauses it and a repair that returns the floor.', 'Use it to help a couple handle frequent interrupting as a shared pattern with a fix rather than a character flaw to argue about.', array['Couples']::text[], '30 minutes', 'When one partner interrupts often, the other stops talking and starts resenting, and the interrupting partner feels policed. The agreement names the pattern without blame, has the interrupting partner describe what happens in their head (the thought will be gone if they wait), and has the other describe what it feels like to be cut off. Then they agree on a signal, a raised finger or a word, that pauses the interruption without a lecture, and a repair line that gives the floor back. The interrupting partner gets a way to hold their thought, a notepad or a phrase. Both practice in session.', '[{"id": "f0", "type": "textarea", "label": "Interrupting partner: what happens in my head in the second before I interrupt:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what it feels like when I am cut off, and what I do with it:"}, {"id": "f2", "type": "textarea", "label": "Our signal that pauses an interruption, and how it is given kindly:"}, {"id": "f3", "type": "textarea", "label": "Our repair line that gives the floor back:"}, {"id": "f4", "type": "textarea", "label": "How the interrupting partner will hold a thought until it is their turn:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: how often the signal was used, and how it landed for each of us:"}]'::jsonb, array['ADHD', 'couples', 'communication']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('substance-free-weekend-hour-by-hour-plan-sheet', 'Substance-Free Weekend Hour by Hour Plan Sheet', 'worksheet'::resource_kind, 'A planner that maps a whole weekend hour by hour, marking the hours that used to involve substance use and what fills each one now.', 'Use it to help a client whose weekends are the hard part see the empty hours in advance and give each one a job.', array['Adults']::text[], '30 minutes to plan, one weekend to use', 'Weekends collapse structure, and the hours that used to hold substance use become open and loud. The sheet is a grid from Friday evening to Sunday night. The client marks the hours that used to involve use, and then plans each of those hours with a place, a person or a task; the hours do not have to be fun, they have to be accounted for. Build in a call with someone for the hardest hour. Review on Monday what held and which hour was hardest; next weekend''s plan starts from that hour. Watch for a plan with no rest in it, which does not survive Saturday afternoon.', '[{"id": "f0", "type": "textarea", "label": "The hours this weekend that used to involve substance use:"}, {"id": "f1", "type": "textarea", "label": "Friday evening: where I will be, with whom, doing what:"}, {"id": "f2", "type": "textarea", "label": "Saturday, hour by hour: what fills each of the marked hours:"}, {"id": "f3", "type": "textarea", "label": "Sunday, hour by hour, including the evening:"}, {"id": "f4", "type": "textarea", "label": "The hardest hour, and who I will call during it:"}, {"id": "f5", "type": "textarea", "label": "Monday review: which hours held, and which one was hardest and why:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('the-weekend-does-not-count-rule-check-sheet', 'The Weekend Does Not Count Rule Check Sheet', 'cbt'::resource_kind, 'A sheet for the rules that carve exceptions out of a substance use goal, like weekends do not count, written down and examined.', 'Use it to help a client find the quiet rules that give urges a schedule and test what the rules are really for.', array['Adults']::text[], '25 minutes', 'Most clients working on substance use have exception rules they have never said aloud: weekends do not count, vacations do not count, it is fine if someone else buys it. The sheet gets the rules written in the client''s own words, asks what each rule allows and when it was made, and then examines the evidence: how use on the exception days has actually gone, and what the rule would sound like if a friend said it. The client decides which rules to keep, rewrite or drop. A kept rule is fine if it is chosen in daylight; the problem is rules that run unnoticed.', '[{"id": "f0", "type": "textarea", "label": "My exception rules, in my own words (weekends, holidays, after a hard week, if someone else is buying):"}, {"id": "f1", "type": "textarea", "label": "For each rule: what it allows, and when I think I made it:"}, {"id": "f2", "type": "textarea", "label": "How my use has actually gone on the exception days:"}, {"id": "f3", "type": "textarea", "label": "What the rule would sound like if a friend said it to me:"}, {"id": "f4", "type": "textarea", "label": "Which rules I will keep on purpose, which I will rewrite, and which I will drop:"}, {"id": "f5", "type": "textarea", "label": "The rewritten rules, written the way I want them now:"}]'::jsonb, array['addiction', 'urges', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('reasons-versus-values-for-staying-substance-free-page', 'Reasons Versus Values for Staying Substance-Free Page', 'act'::resource_kind, 'A page that sorts the client''s reasons for not using into reasons that argue and values that pull, and asks which hold on a hard night.', 'Use it to help a client find the pull under the reasons so they are not relying on winning an argument with an urge.', array['Adults']::text[], '25 minutes', 'Reasons are arguments and urges are good at arguing back: the health reason can be answered with one more will not matter, the money reason with I earned it. Values do not argue; they pull. The page lists every reason the client gives for staying substance-free, then asks for each whether it is a case to be made or a direction they want to go. Then it asks which have held on hard nights. Usually the ones that held were values: being the parent who shows up, being someone whose word is good. The client writes those in their own words to carry.', '[{"id": "f0", "type": "textarea", "label": "All the reasons I give for not using, as I usually say them:"}, {"id": "f1", "type": "textarea", "label": "For each: is it an argument the urge can answer, or a direction I want to go?"}, {"id": "f2", "type": "textarea", "label": "On the hardest recent night, which ones held and which ones got argued away?"}, {"id": "f3", "type": "textarea", "label": "The values underneath, in my own plain words:"}, {"id": "f4", "type": "textarea", "label": "Where I will carry these words so they are there on the next hard night:"}]'::jsonb, array['addiction', 'defusion', 'values']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-replying-to-an-old-using-friend-card', 'Wise Mind Before Replying to an Old Using Friend Card', 'dbt'::resource_kind, 'A wise mind card for the message from someone the client used with, finding the quiet answer under the pull and the rulebook.', 'Use it to help a client decide how to answer a message from an old using friend without the urge or the rulebook deciding for them.', array['Adults']::text[], '15 minutes', 'A message from someone the client used with pulls hard in two directions: emotion mind misses them and wants the old ease back, and reasonable mind quotes the rule about cutting everyone off. The card asks the client to write what each mind says, then settle for a few minutes and ask what they know underneath. Wise mind answers vary: a warm reply and no meeting, a meeting somewhere specific in daylight, no reply at all. The card also plans what the client will do in the ten minutes after replying, because the urge often comes after the message is sent, not before.', '[{"id": "f0", "type": "textarea", "label": "The message, and who it is from:"}, {"id": "f1", "type": "textarea", "label": "Emotion mind: everything I feel reading it, including what I miss:"}, {"id": "f2", "type": "textarea", "label": "Reasonable mind: the rules and the risks:"}, {"id": "f3", "type": "textarea", "label": "After settling: what I know underneath both, and the reply that fits it (or no reply):"}, {"id": "f4", "type": "textarea", "label": "What I will do in the ten minutes after I reply or decide not to:"}]'::jsonb, array['addiction', 'wise mind', 'urges']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('clear-evening-plan-build-relay-game', 'Clear Evening Plan Build Relay Game', 'game'::resource_kind, 'A team game where groups build a substance-free evening plan in timed rounds, with a card for the hard hour.', 'Use it to get a group generating evening plans fast and borrowing each other''s ideas for the hour that is hardest.', array['Adults', 'Teens', 'Groups']::text[], '35 minutes', 'Teams of three or four get a stack of category cards: place, people, something to eat, something to do, the hard hour, the exit. Each round is three minutes; a team fills one card and passes the plan to the next team, which fills the next card without undoing earlier choices. After six rounds every plan is complete and read aloud. Points for a plan a team member would actually do, a bonus for the best answer to the hard hour card. Debrief: which hard hour answers would work for you, and which plans fell apart because one card was unrealistic.', '[{"id": "f0", "type": "textarea", "label": "The plan my team ended up with, card by card:"}, {"id": "f1", "type": "textarea", "label": "The best hard hour answer I heard from any team:"}, {"id": "f2", "type": "textarea", "label": "A card that made a plan unrealistic, and what would fix it:"}, {"id": "f3", "type": "textarea", "label": "A plan I would actually do, and what would make it mine:"}, {"id": "f4", "type": "textarea", "label": "The one idea I am taking home for my own next evening:"}]'::jsonb, array['addiction', 'game', 'planning']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('door-slam-and-stomp-habit-replacement-sheet', 'Door Slam and Stomp Habit Replacement Sheet', 'worksheet'::resource_kind, 'A sheet for physical anger habits like slamming doors, with what each one does for the client and a replacement that does the same job.', 'Use it to help a client swap a physical anger habit for one that discharges the same energy without the damage.', array['Adults', 'Teens']::text[], '20 minutes', 'Slamming a door or stomping off is not nothing; it discharges energy and makes a point. A replacement has to do both jobs or it will not stick. The sheet lists the client''s physical anger habits, asks what each one does for them (release, signal, exit) and what it costs (a scared child, a broken hinge, a reputation). Then they design a replacement per habit: a closed door shut hard with the hand on it, a fast walk around the block, a signal word that means I am leaving to cool down. Practice the replacements on calm days so they are available on hot ones.', '[{"id": "f0", "type": "textarea", "label": "My physical anger habits (slamming, stomping, throwing, punching a wall):"}, {"id": "f1", "type": "textarea", "label": "For each: what it does for me (release, signal, exit) and what it costs:"}, {"id": "f2", "type": "textarea", "label": "A replacement for each that does the same job without the cost:"}, {"id": "f3", "type": "textarea", "label": "The signal I will give the people in the room before I use it:"}, {"id": "f4", "type": "textarea", "label": "Practicing on a calm day: what the replacement felt like, and what I would change:"}, {"id": "f5", "type": "textarea", "label": "After a week: which habits came back, and which replacements showed up:"}]'::jsonb, array['anger management', 'habits', 'de-escalation']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('everyone-is-incompetent-standards-check-sheet', 'Everyone Is Incompetent Standards Check Sheet', 'cbt'::resource_kind, 'A sheet for anger fueled by the belief that other people are incompetent, with the hidden standard named and tested for fairness.', 'Use it to help a client whose anger comes from other people falling short find the standard they are being held to.', array['Adults']::text[], '20 minutes', 'Clients who are angry at incompetence everywhere are usually carrying a standard they have never written down and holding strangers, coworkers and family to it. The sheet takes a recent incident, records the thought about the other person, and then asks for the standard underneath (people should know how to do their jobs, if I can do it anyone can). It asks whether the client holds themselves to the same standard, whether they always met it when learning, and what the standard costs them in blood pressure and relationships. The rewrite usually keeps the preference and drops the should.', '[{"id": "f0", "type": "textarea", "label": "The incident, and the thought I had about the other person:"}, {"id": "f1", "type": "textarea", "label": "The standard underneath, in my words: people should..."}, {"id": "f2", "type": "textarea", "label": "Do I hold myself to the same standard? When I was learning this, did I meet it?"}, {"id": "f3", "type": "textarea", "label": "What the standard costs me (how often I am angry, who avoids me):"}, {"id": "f4", "type": "textarea", "label": "A rewrite that keeps my preference and drops the should:"}, {"id": "f5", "type": "textarea", "label": "How I would have handled the incident with the rewrite in mind:"}]'::jsonb, array['anger management', 'thinking traps', 'core beliefs']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('needing-the-last-word-noticing-page', 'Needing the Last Word Noticing Page', 'act'::resource_kind, 'A noticing page for the pull to get the last word in an argument, with the hook named and a week of noticing when it bites.', 'Use it to help a client see the last word as a hook rather than a victory, and practice letting the other person have it.', array['Adults', 'Teens']::text[], '15 minutes to set up, one week of noticing', 'The last word feels like winning and costs the whole evening. The page asks the client to describe the pull in the body and the thought that goes with it (I cannot let that stand), and what the last word has actually gotten them in past arguments. Then a week of noticing: each time the hook bites, they record it and whether they took the bait. Letting the other person have the last word is the practice; it is not agreeing, it is unhooking. Expect the mind to call it losing for a while. Ask what they did with the evening they got back.', '[{"id": "f0", "type": "textarea", "label": "What the pull for the last word feels like in my body, and the thought that comes with it:"}, {"id": "f1", "type": "textarea", "label": "What the last word has actually gotten me in past arguments:"}, {"id": "f2", "type": "textarea", "label": "This week, each time the hook bit: the situation, and whether I took the bait:"}, {"id": "f3", "type": "textarea", "label": "A time I let them have it: what my mind said, and what happened to the evening:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the arguments that ended without my last word:"}]'::jsonb, array['anger management', 'defusion', 'choice point']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-that-they-will-not-apologize-card', 'Radical Acceptance That They Will Not Apologize Card', 'dbt'::resource_kind, 'A radical acceptance card for the apology that is not coming, with the fact stated, the fight against it noticed, and the body let go.', 'Use it to help a client stop waiting for an apology that keeps their anger on hold and get their energy back.', array['Adults', 'Teens']::text[], '15 minutes, repeated', 'Some anger stays alive for years on the expectation of an apology that the other person will never give. Radical acceptance here is not forgiveness and not approval; it is accepting the fact that the apology is not coming, so the client can stop organizing their life around waiting for it. The card states the fact plainly, names how the client fights it (replaying, rehearsing speeches, bringing it up), notices what the fight costs, and turns the mind toward acceptance with the body relaxed, willing hands, a long exhale. Repeat; the mind will turn back. That is normal.', '[{"id": "f0", "type": "textarea", "label": "The fact, stated plainly: they are not going to apologize for..."}, {"id": "f1", "type": "textarea", "label": "How I fight that fact (replaying, rehearsing what I would say, bringing it up, waiting):"}, {"id": "f2", "type": "textarea", "label": "What the fighting costs me in a week:"}, {"id": "f3", "type": "textarea", "label": "Turning my mind toward the fact, with willing hands and a long exhale: what I notice:"}, {"id": "f4", "type": "textarea", "label": "What I would do with the energy if I were not waiting:"}]'::jsonb, array['anger management', 'radical acceptance', 'acceptance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('angry-scribble-to-smooth-lines-drawing-play', 'Angry Scribble to Smooth Lines Drawing Play', 'kids'::resource_kind, 'A drawing activity where the child scribbles the anger hard and fast, then slows the hand into smooth lines beside the parent.', 'Use it to give a child a way to move anger out through the hand and feel the shift from fast to slow.', array['Children']::text[], '15 minutes, repeatable', 'The child gets a crayon and a big sheet and scribbles as hard and fast as the anger feels, with the parent scribbling on their own sheet beside them. When the scribble is done, both turn to a fresh page and draw slow, smooth lines, waves or spirals, breathing with the lines. Parent and child compare the two pages and name what each felt like in the hand. The parent''s job is to scribble too, not to watch, and to let the scribble be as ugly as it needs to be. Keep both pages; the child can choose to tear up the scribble or keep it as proof the anger moved.', '[{"id": "f0", "type": "textarea", "label": "My scribble page: what my hand and my body felt like while I did it:"}, {"id": "f1", "type": "textarea", "label": "My smooth lines page: what changed in my hand and my breathing:"}, {"id": "f2", "type": "textarea", "label": "Parent: what my own two pages felt like:"}, {"id": "f3", "type": "textarea", "label": "What I want to do with my scribble page (keep it, tear it, fold it away):"}, {"id": "f4", "type": "textarea", "label": "When I could use scribble-then-smooth this week, and where the paper will be:"}]'::jsonb, array['anger management', 'children', 'drawing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('hand-washing-minutes-and-pump-count-baseline-sheet', 'Hand Washing Minutes and Pump Count Baseline Sheet', 'worksheet'::resource_kind, 'A baseline sheet that records each hand wash for three days: the trigger, the minutes, the soap pumps and the feeling that ended it.', 'Use it to get a plain count of washing before anything changes, so the client and you both know what the baseline is.', array['Adults', 'Teens']::text[], 'Three days of entries', 'Clients often have no idea how long or how often they wash; they know it is too much and that is all. The sheet collects three days of entries: what prompted the wash, how long it took, how many pumps of soap, and what ended it (a count, a feeling, someone waiting). Nothing is asked to change yet. Review the pattern together: which triggers, what the ending feeling is, and the total minutes a day. The baseline makes later work concrete and gives the client a number that is theirs. Watch for washing that is hidden from the log; ask gently.', '[{"id": "f0", "type": "textarea", "label": "What prompted this wash:"}, {"id": "f1", "type": "textarea", "label": "How long it took, in minutes, and how many pumps of soap:"}, {"id": "f2", "type": "textarea", "label": "What ended it (a number, a feeling of done, someone waiting, the water going cold):"}, {"id": "f3", "type": "textarea", "label": "How I felt right after, 0 to 10, and ten minutes later:"}, {"id": "f4", "type": "textarea", "label": "Day''s total: number of washes and total minutes:"}, {"id": "f5", "type": "textarea", "label": "After three days: the triggers that came up most, and what I notice about the ending feeling:"}]'::jsonb, array['OCD', 'rituals', 'self-monitoring']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('chain-of-unlikely-steps-probability-sheet', 'Chain of Unlikely Steps Probability Sheet', 'cbt'::resource_kind, 'A sheet that breaks a feared catastrophe into the chain of steps that would all have to happen, with the odds multiplied out.', 'Use it to help a client see how many unlikely things have to line up for the feared outcome, and what the whole chain comes to.', array['Adults', 'Teens']::text[], '20 minutes', 'A feared outcome usually feels like one event; it is almost always a chain. The stove left on has to actually be on, and stay on, and something has to be near it, and catch, and nobody notice, and the alarm not sound. The sheet lays the chain out step by step, asks the client to put a rough probability on each one, and multiplies them. The result is usually a number so small the client laughs, which is a start. Then they rate how much the fear has changed. The sheet does not say the fear is silly; it shows how the mind skips the chain.', '[{"id": "f0", "type": "textarea", "label": "The feared outcome, as a single sentence:"}, {"id": "f1", "type": "textarea", "label": "Every step that would have to happen, in order, for it to occur:"}, {"id": "f2", "type": "textarea", "label": "My rough probability for each step, as a percentage or a fraction:"}, {"id": "f3", "type": "textarea", "label": "All the steps multiplied together: what the whole chain comes to:"}, {"id": "f4", "type": "textarea", "label": "How strongly the fear felt before, 0 to 100, and how strongly it feels now:"}, {"id": "f5", "type": "textarea", "label": "What my mind did with the chain: which steps it skipped when it jumped to the end:"}]'::jsonb, array['OCD', 'predictions', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('values-hour-rituals-are-not-invited-page', 'Values Hour Rituals Are Not Invited Page', 'act'::resource_kind, 'A committed action page that sets one hour a week for a valued activity where urges to ritualize are noticed, not performed.', 'Use it to help a client reclaim one hour for what matters to them with the urges to ritualize riding along uninvited.', array['Adults', 'Teens']::text[], '20 minutes to plan, one hour weekly', 'Rituals take time from everything the client values, and the usual response is to wait until the rituals are gone before living. The page picks one valued activity (cooking with a child, a walk with a friend, an hour of music) and sets the hour. During it, the client notices each urge to check, wash or review, names it, and continues the activity without doing the ritual, if they can; if they cannot, they note it and return to the activity. Afterward they record what the urges did and what the hour gave them. The win is the hour, not the count of urges resisted.', '[{"id": "f0", "type": "textarea", "label": "The valued activity, and why it matters to me:"}, {"id": "f1", "type": "textarea", "label": "When the hour is, and who is with me:"}, {"id": "f2", "type": "textarea", "label": "The urges I expect to show up during it:"}, {"id": "f3", "type": "textarea", "label": "What I will say to an urge when it arrives, and how I will return to the activity:"}, {"id": "f4", "type": "textarea", "label": "After: what the urges did over the hour, and what the hour gave me:"}]'::jsonb, array['OCD', 'committed action', 'values']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-toward-an-intrusive-image-card', 'Nonjudgmental Stance Toward an Intrusive Image Card', 'dbt'::resource_kind, 'A card for meeting an intrusive image with the DBT nonjudgmental stance: describing what the image is without calling it or oneself bad.', 'Use it to help a client separate an unwanted image from the verdict they pass on themselves for having it.', array['Adults', 'Teens']::text[], 'Ten minutes, repeated', 'The image is bad enough; the judgment that follows (what kind of person has a thought like that) is what keeps the client up. The card practices describing the image in neutral terms, an image of, lasting about, that came while I was, and then noticing the judgment as a separate event: and then I had the thought that I am dangerous. Rate the distress for the image alone and for the judgment. Most clients find the judgment carries more than the image. Remind them that having an image is not an intention; the card practices saying that without arguing with the image.', '[{"id": "f0", "type": "textarea", "label": "Describing the image in neutral words: an image of... that came while I was..."}, {"id": "f1", "type": "textarea", "label": "The judgment that followed, as a separate sentence: and then I had the thought that..."}, {"id": "f2", "type": "textarea", "label": "Distress from the image alone, 0 to 10, and from the judgment, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What I did with the image this time (pushed, argued, checked, let it sit):"}, {"id": "f4", "type": "textarea", "label": "What I notice when I describe it without the judgment attached:"}]'::jsonb, array['OCD', 'mindfulness', 'intrusive thoughts']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('pass-the-shared-pen-group-game', 'Pass the Shared Pen Group Game', 'game'::resource_kind, 'A group game where one pen is passed hand to hand to sign a shared page, with the urge to wipe or wash noticed and rated each round.', 'Use it to let a group practice touching a shared object together, with the discomfort out loud and the laughter shared.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'One pen, one page. Each player signs their name and passes the pen directly into the next hand, no wiping, no sleeve. Round two, each adds a doodle and passes again. Round three, the pen goes round twice as fast. After each round every player calls out their urge to wipe or wash, 0 to 10, and the group watches the numbers move. No one leaves to wash until the debrief is done. The debrief asks what happened to the urge between rounds and what the hands feel like now. For players for whom this is a real exposure step, agree beforehand which rounds they will join.', '[{"id": "f0", "type": "textarea", "label": "My urge to wipe or wash after round one, two and three, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "What my mind said about the pen and other people''s hands:"}, {"id": "f2", "type": "textarea", "label": "What happened to the urge while I waited through the debrief:"}, {"id": "f3", "type": "textarea", "label": "What my hands actually feel like right now:"}, {"id": "f4", "type": "textarea", "label": "One shared object I avoid in daily life that this game makes me think about:"}]'::jsonb, array['OCD', 'game', 'exposure']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('places-i-stopped-going-since-the-first-surge-inventory', 'Places I Stopped Going Since the First Surge Inventory', 'worksheet'::resource_kind, 'An inventory of places, routes and situations given up since panic started, with a date, a reason and how much each is missed.', 'Use it to show a client the full map of what panic has taken so the return trips can be chosen rather than avoided.', array['Adults', 'Teens']::text[], '25 minutes', 'Avoidance after panic grows one place at a time and the client rarely sees the whole map. The inventory lists each place, route, or situation they no longer go to or only go to with company, roughly when it was dropped, what the surge there was like or what they fear it would be, and how much they miss it. Sort by missed; the most-missed, least-feared item is the first return trip. Keep the tone practical. Clients are often shocked at the length of the list, and that shock is useful fuel for the work that follows.', '[{"id": "f0", "type": "textarea", "label": "Places and routes I no longer go to since the panic started:"}, {"id": "f1", "type": "textarea", "label": "Places I only go to with someone, or with an escape plan:"}, {"id": "f2", "type": "textarea", "label": "For each: roughly when I stopped, and what happened or what I fear would happen there:"}, {"id": "f3", "type": "textarea", "label": "How much I miss each one, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "The one I miss most and fear least: my first return trip, and when:"}]'::jsonb, array['panic attacks', 'avoidance', 'hierarchy']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('dizziness-means-i-will-faint-fact-check-sheet', 'Dizziness Means I Will Faint Fact Check Sheet', 'cbt'::resource_kind, 'A fact sheet for the belief that panic dizziness leads to fainting, with the client''s own record and what the body does in a surge.', 'Use it to help a client test the dizziness-to-fainting prediction against their own history and what their body actually does.', array['Adults', 'Teens']::text[], '20 minutes', 'The fear of fainting in public keeps many clients out of stores and lines, and it rests on a belief that dizziness is the first step. The sheet asks for the client''s complete fainting history, how many surges they have had and how many ended in fainting, and what they know about their heart rate and blood pressure during panic (both go up; fainting usually involves a drop). Then they rate the prediction before and after. For clients with a history of fainting from blood or needles, note that fear and that experience differ and that this sheet is about the panic surge.', '[{"id": "f0", "type": "textarea", "label": "The prediction, in my words: when I get dizzy during a surge, I will..."}, {"id": "f1", "type": "textarea", "label": "How many surges I have had, roughly, and how many times I actually fainted during one:"}, {"id": "f2", "type": "textarea", "label": "Times I have fainted in my life, if any, and what caused each one:"}, {"id": "f3", "type": "textarea", "label": "What I know about heart rate and blood pressure during a surge, and what has to happen for a person to faint:"}, {"id": "f4", "type": "textarea", "label": "How much I believed the prediction before, 0 to 100, and now:"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time dizziness arrives mid-surge, instead of sitting down or leaving:"}]'::jsonb, array['panic attacks', 'thinking traps', 'evidence']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('letting-the-heart-pound-hands-open-page', 'Letting the Heart Pound Hands Open Page', 'act'::resource_kind, 'A willingness page for a pounding heart: hands turned palm-up, the heart allowed to do what it is doing, timed and logged.', 'Use it to help a client replace bracing against a racing heart with a posture of allowing it, and see what the heart does when allowed.', array['Adults', 'Teens']::text[], '10 minutes per practice, one week', 'When the heart races, the body braces: fists, held breath, shoulders up, which the mind reads as more danger. The page teaches a different posture: hands open and palm-up on the knees, breath left alone, attention on the heartbeat as a sensation with a rhythm and a location. The client lets it pound for as long as it does and times it. Practice first with a mildly raised heart rate (a flight of stairs) in session. The log records how long the pounding lasted with hands open and what the mind said. Most clients find allowed pounding is shorter than fought pounding.', '[{"id": "f0", "type": "textarea", "label": "Where I feel my heartbeat when it pounds, and what I usually do with my hands and shoulders:"}, {"id": "f1", "type": "textarea", "label": "Practicing with hands open after the stairs: how long the pounding lasted, in minutes:"}, {"id": "f2", "type": "textarea", "label": "What my mind said while I let it pound:"}, {"id": "f3", "type": "textarea", "label": "During a real surge this week: did I get my hands open? How long did it last?"}, {"id": "f4", "type": "textarea", "label": "What I notice about pounding that is allowed versus pounding that is fought:"}]'::jsonb, array['panic attacks', 'willingness', 'acceptance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('participate-keep-talking-through-a-surge-card', 'Participate Keep Talking Through a Surge Card', 'dbt'::resource_kind, 'A participate skill card for staying in a conversation while a surge rises, attention thrown into the other person''s words.', 'Use it to give a client who goes silent and leaves when a surge starts a way to stay in the moment they are already in.', array['Adults', 'Teens']::text[], 'Five minutes to plan, use as needed', 'The participate skill means throwing oneself fully into the current activity, and when the current activity is a conversation, that is the skill. The card plans it: when the surge starts, the client keeps their eyes on the other person, asks a question, listens to the answer closely enough to repeat it, and lets the body do what it is doing in the background. The card includes a prepared line in case they need a moment (give me one second, I lost my thread) that does not end the conversation. Review afterward what the surge did while attention was elsewhere.', '[{"id": "f0", "type": "textarea", "label": "My sign that a surge is starting during a conversation:"}, {"id": "f1", "type": "textarea", "label": "The question I will ask the other person to pull my attention into their words:"}, {"id": "f2", "type": "textarea", "label": "My one-second line if I need it, that keeps the conversation going:"}, {"id": "f3", "type": "textarea", "label": "What I will let my body do in the background without attending to it:"}, {"id": "f4", "type": "textarea", "label": "After a real try: what the surge did while I was listening, and how long it lasted:"}]'::jsonb, array['panic attacks', 'mindfulness', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('rating-a-surge-together-afterward-debrief-sheet-for-partners', 'Rating a Surge Together Afterward Debrief Sheet for Partners', 'couples'::resource_kind, 'A debrief sheet a couple fills in together after a panic surge: what each saw, what helped, and one change for next time.', 'Use it to help a couple learn from each surge together instead of one partner apologizing and the other walking on eggshells.', array['Couples']::text[], '15 minutes after a surge', 'After a surge the partner who panicked often apologizes and the other partner is quietly shaken, and neither says what they noticed. The sheet is filled in together within a day: what each saw and felt, how long it lasted by each person''s estimate, what the supporting partner did that helped and what made it worse, and what the panicking partner wished for. One change for next time, agreed by both. Over several surges a pattern appears, and the couple becomes a team with a method. Watch for the supporting partner taking over the debrief; both voices in every box.', '[{"id": "f0", "type": "textarea", "label": "Panicking partner: what I noticed first, and how long it felt like it lasted:"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what I noticed first, and how long I think it lasted:"}, {"id": "f2", "type": "textarea", "label": "What my partner did that helped (panicking partner answers):"}, {"id": "f3", "type": "textarea", "label": "What I did that I think made it worse, or that I was unsure about (supporting partner answers):"}, {"id": "f4", "type": "textarea", "label": "What each of us wished the other had done:"}, {"id": "f5", "type": "textarea", "label": "Our one change for next time:"}]'::jsonb, array['panic attacks', 'couples', 'support']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('teen-curfew-negotiation-prep-sheet', 'Teen Curfew Negotiation Prep Sheet', 'worksheet'::resource_kind, 'A prep sheet for a parent before a curfew talk, with the real concern named and the non-negotiables separated from the flexible parts.', 'Use it to help a parent go into a curfew talk clear on what they are protecting and where they can give.', array['Adults']::text[], '20 minutes', 'Curfew fights go badly when the parent argues the number instead of the concern. The sheet asks what the curfew is actually for (sleep, safety on the road, knowing where the teen is), which parts are non-negotiable and which could move, what the teen will probably argue and what is fair in their argument, and what the parent will offer in exchange for compliance. It also asks how the parent will handle the moment the teen gets rude. A parent who has written the concern down can say it in one sentence, which changes the conversation.', '[{"id": "f0", "type": "textarea", "label": "What the curfew is actually protecting, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "The parts I will not move on, and why:"}, {"id": "f2", "type": "textarea", "label": "The parts I could flex on (weekends, special events, a check-in text instead of a time):"}, {"id": "f3", "type": "textarea", "label": "What my teen will probably argue, and what is fair in it:"}, {"id": "f4", "type": "textarea", "label": "What I will say when it gets rude, and what I will do if it keeps going:"}, {"id": "f5", "type": "textarea", "label": "After the conversation: what we agreed, and what I would do differently:"}]'::jsonb, array['parenting', 'boundaries', 'communication']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('slammed-door-means-they-hate-me-thought-check-sheet', 'Slammed Door Means They Hate Me Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the parent whose teen''s slammed door gets read as hatred, with the evidence and the alternatives laid out.', 'Use it to help a parent hold a teen''s anger without concluding the relationship is gone.', array['Adults']::text[], '15 minutes', 'A teen''s slammed door lands on a parent as a verdict, and the parent either pursues for reassurance or withdraws in hurt, both of which the teen reads badly. The sheet records the moment, the automatic thought, and the feeling, then asks for evidence on both sides, including what the teen did later that evening, how the parent treated their own parents at that age, and what a slammed door usually means developmentally (a boundary, a flood, a need for space). The rewrite keeps the hurt and drops the verdict. Then a plan for what the parent does in the next hour.', '[{"id": "f0", "type": "textarea", "label": "What happened, and the thought I had as the door slammed:"}, {"id": "f1", "type": "textarea", "label": "How I felt, and how strongly:"}, {"id": "f2", "type": "textarea", "label": "Evidence for the thought, and evidence against it (including what they did later):"}, {"id": "f3", "type": "textarea", "label": "What I did to my own parents at that age, and what it meant:"}, {"id": "f4", "type": "textarea", "label": "What a slammed door more likely means right now:"}, {"id": "f5", "type": "textarea", "label": "What I will do in the next hour, and what I will say when they come out:"}]'::jsonb, array['parenting', 'thought record', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('parenting-values-at-the-video-game-standoff-page', 'Parenting Values at the Video Game Standoff Page', 'act'::resource_kind, 'A values page for the nightly standoff over turning off the game, with the parent''s move chosen before the standoff starts.', 'Use it to help a parent act from their values at the screen-time standoff instead of from the frustration of the moment.', array['Adults']::text[], '20 minutes', 'The standoff over the game runs the same way every night: a warning, an argument, a threat, a worse evening. The page asks the parent what kind of parent they want to be at that moment (calm, consistent, warm, firm), what they actually do when hooked, and what move would serve the value: a timer the child sets, a five-minute warning, sitting down beside them to watch the last round, a consequence stated once and followed. Then the parent picks one move to try for a week. The game is not the point; the parent''s conduct is the thing they control.', '[{"id": "f0", "type": "textarea", "label": "The standoff, as it usually goes, step by step:"}, {"id": "f1", "type": "textarea", "label": "The kind of parent I want to be in that moment, in a few words:"}, {"id": "f2", "type": "textarea", "label": "What I actually do when I am hooked by frustration:"}, {"id": "f3", "type": "textarea", "label": "Moves that would serve my values at the standoff (list several):"}, {"id": "f4", "type": "textarea", "label": "The one move I will try this week, and what I will say:"}, {"id": "f5", "type": "textarea", "label": "After a week: how the standoff went, and whether I was the parent I wanted to be, regardless of how the child reacted:"}]'::jsonb, array['parenting', 'values', 'choice point']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('one-mindful-bath-time-card-for-parents', 'One-Mindful Bath Time Card for Parents', 'dbt'::resource_kind, 'A card for giving a child''s bath time full attention for ten minutes, phone elsewhere, as a daily one-mindfulness practice.', 'Use it to give a parent who is always half somewhere else one daily ten-minute window of full presence with their child.', array['Adults']::text[], 'Ten minutes daily', 'One-mindfulness means doing one thing at a time with full attention, and bath time is a natural container: it has a start and an end, a child in front of you, and water to notice. The card sets the terms: phone in another room, no planning tomorrow, attention on the sounds, the child''s face, the warmth. When the mind wanders to the list, the parent notes it and returns. The card logs how many times the mind left and one thing the parent noticed about their child that they would have missed. Any routine works if there is no bath.', '[{"id": "f0", "type": "textarea", "label": "Where my phone will be, and what I will tell myself when I want to check it:"}, {"id": "f1", "type": "textarea", "label": "Tonight: what I noticed with my senses during the ten minutes:"}, {"id": "f2", "type": "textarea", "label": "How many times my mind left for the list, roughly, and how I came back:"}, {"id": "f3", "type": "textarea", "label": "One thing about my child I noticed that I would have missed:"}, {"id": "f4", "type": "textarea", "label": "After a week: what changed in bath time, for me and for them:"}]'::jsonb, array['parenting', 'mindfulness', 'routines']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('inside-voice-volume-meter-poster-craft', 'Inside Voice Volume Meter Poster Craft', 'kids'::resource_kind, 'A craft where the child makes a volume meter poster with a moving arrow, and the parent uses it to point rather than shout about noise.', 'Use it to give a family a shared, visual language for voice volume that replaces the parent yelling for quiet.', array['Children']::text[], '30 minutes to make, used daily', 'The child draws a meter with levels they name themselves (mouse, inside, outside, stadium) and colors each one, and a paper arrow goes on with a pin or a paper clip. The poster goes where the loudest moments happen. When the volume climbs, the parent points to the level they need instead of raising their own voice to ask for quiet. The child gets to set the arrow too, including on the parent. Coach the parent that the meter is for everyone in the house, and that pointing at it calmly when they are frustrated is the whole practice.', '[{"id": "f0", "type": "textarea", "label": "Draw my meter: the levels, their names and their colors:"}, {"id": "f1", "type": "textarea", "label": "Where the poster will go, and why that spot:"}, {"id": "f2", "type": "textarea", "label": "When the arrow goes up, what the grown-up does instead of shouting:"}, {"id": "f3", "type": "textarea", "label": "When I think a grown-up is too loud, what I get to do:"}, {"id": "f4", "type": "textarea", "label": "Parent: the moment this week I will practice pointing instead of raising my voice:"}]'::jsonb, array['parenting', 'children', 'craft']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('nicu-day-rhythm-and-breaks-sheet', 'NICU Day Rhythm and Breaks Sheet', 'worksheet'::resource_kind, 'A daily rhythm sheet for a parent with a baby in the NICU: the visits, the pumping or feeds, the drive, and the breaks nobody is scheduling.', 'Use it to help a parent living between home and the NICU build a day that includes rest without feeling like abandonment.', array['Adults']::text[], '20 minutes to plan, daily use', 'Parents with a baby in intensive care often spend every possible minute at the bedside and run themselves down to nothing within a week. The sheet maps a day: the hospital hours, the rounds they want to be present for, the feeds or pumping schedule, the drive, and then the parts that get skipped: a meal, a shower, an hour of sleep, a conversation that is not about the baby. It asks who else can be at the bedside and what the client fears will happen if they leave. The fear is usually spoken for the first time here. A rested parent is part of the baby''s care; say that plainly.', '[{"id": "f0", "type": "textarea", "label": "The hospital hours that matter most to me (rounds, a feed, a doctor''s visit) and when they are:"}, {"id": "f1", "type": "textarea", "label": "The parts of the day that keep getting skipped (meals, shower, sleep, fresh air):"}, {"id": "f2", "type": "textarea", "label": "Who else could be at the bedside, and when:"}, {"id": "f3", "type": "textarea", "label": "What I am afraid will happen if I leave for two hours:"}, {"id": "f4", "type": "textarea", "label": "Today''s rhythm, hour by hour, with at least one break in it:"}, {"id": "f5", "type": "textarea", "label": "After three days: what held, and what I notice about the days I took the break:"}]'::jsonb, array['perinatal and postpartum', 'pacing', 'support']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('baby-prefers-my-partner-thought-check-sheet', 'Baby Prefers My Partner Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the parent who believes the baby prefers the other parent, with the evidence sorted and the verdict dropped.', 'Use it to help a new parent hold a baby''s fussing without reading it as rejection.', array['Adults']::text[], '15 minutes', 'A baby who settles for the other parent and fusses for this one sets off a cascade: the baby prefers them, I am not a natural, I am failing. The sheet records the moment and the thought, then collects the evidence: times the baby settled with this parent, times the baby fussed with the other, what was different (feeding, tiredness, who had been holding them, the time of day). It asks what babies do with attention in their first months and how much of it is about the parent at all. The rewrite stays with the fact (the baby fussed) and drops the verdict.', '[{"id": "f0", "type": "textarea", "label": "What happened, and the thought that followed:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe the baby prefers my partner, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "Times the baby settled with me this week, and times they fussed with my partner:"}, {"id": "f3", "type": "textarea", "label": "What was different in the moments the baby fussed with me (time of day, tiredness, hunger, who had held them):"}, {"id": "f4", "type": "textarea", "label": "What I know about what babies in these months do with their attention:"}, {"id": "f5", "type": "textarea", "label": "A rewrite that keeps the fact and drops the verdict:"}]'::jsonb, array['perinatal and postpartum', 'thought record', 'self-criticism']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('values-at-three-in-the-morning-page', 'Values at Three in the Morning Page', 'act'::resource_kind, 'A page for the night feed and the thoughts that come with it, naming the value the parent is living at that hour.', 'Use it to help an exhausted parent find the meaning in the night hours without pretending they are not hard.', array['Adults']::text[], '15 minutes', 'Three in the morning with a baby who will not settle is where the darkest thoughts come. The page asks what the parent''s mind says at that hour and what they do with it, then asks what they are actually doing: feeding, holding, staying. What value is that, in their words? The page does not argue that the hour is fine; it asks what kind of parent they are being while it is awful. Then it plans two small things for the hour (a podcast, a dim lamp, a text to another parent who is up). If the thoughts at that hour turn toward harm, bring them to session and keep 988 (call or text) on the page.', '[{"id": "f0", "type": "textarea", "label": "What my mind says at three in the morning, in its words:"}, {"id": "f1", "type": "textarea", "label": "What I am actually doing at that hour, plainly:"}, {"id": "f2", "type": "textarea", "label": "The value I am living while I do it, in my own words:"}, {"id": "f3", "type": "textarea", "label": "Two small things that would make the hour carryable:"}, {"id": "f4", "type": "textarea", "label": "If thoughts at that hour turn toward hurting myself or the baby: who I will tell, and 988 (call or text) for the moment:"}]'::jsonb, array['perinatal and postpartum', 'values', 'willingness']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('stranger-comments-about-the-baby-check-the-facts-card', 'Stranger Comments About the Baby Check the Facts Card', 'dbt'::resource_kind, 'A check the facts card for a stranger''s comment about the baby, separating what was said from what the parent heard it mean.', 'Use it to help a new parent let a stranger''s remark pass without carrying it home as a judgment.', array['Adults']::text[], 'Five minutes per use', 'Strangers comment on babies: too cold, too hot, hungry, should be sleeping. A tired parent hears a verdict on their competence and carries it for days. The card has the parent write exactly what was said, what they heard it mean, and the emotion and its intensity. Then: does the emotion fit the facts? Did the stranger know anything about this baby? Did they say the parent was failing, or did they say the baby looked cold? The card ends with the response the parent wants ready for next time, which is usually short. Practice saying it aloud in session.', '[{"id": "f0", "type": "textarea", "label": "What the stranger actually said, word for word:"}, {"id": "f1", "type": "textarea", "label": "What I heard it mean about me:"}, {"id": "f2", "type": "textarea", "label": "The emotion and its intensity, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What the stranger knew about my baby and my day: anything?"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts of what was said? What would fit?"}, {"id": "f5", "type": "textarea", "label": "My ready line for next time, short enough to say while walking away:"}]'::jsonb, array['perinatal and postpartum', 'check the facts', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('twins-divide-and-conquer-night-plan-for-partners', 'Twins Divide and Conquer Night Plan for Partners', 'couples'::resource_kind, 'A night plan for partners with twins or multiples, assigning babies, shifts and the handoff, with each partner''s limit named.', 'Use it to help the parents of multiples survive the nights as a team with a plan instead of two people awake and resentful.', array['Couples']::text[], '30 minutes', 'Two babies, two parents, and no plan means both parents are up for every cry and neither sleeps. The sheet has partners design the night: one-baby-each, or shifts with a handoff time, or one parent off duty entirely on alternate nights. Each partner names how many hours they need to function and the point past which they stop being safe to hold a baby. The handoff gets a script so it does not become an argument at four in the morning. Review after a week; multiples change weekly and the plan does too. Watch for the partner who insists they are fine on no sleep.', '[{"id": "f0", "type": "textarea", "label": "Partner one: hours of sleep I need to function, and the point past which I am not safe with a baby:"}, {"id": "f1", "type": "textarea", "label": "Partner two: hours of sleep I need to function, and the point past which I am not safe with a baby:"}, {"id": "f2", "type": "textarea", "label": "Our night plan: one baby each, shifts, or alternate nights, with the times:"}, {"id": "f3", "type": "textarea", "label": "The handoff: when, where, and the exact words so it is not a negotiation at four in the morning:"}, {"id": "f4", "type": "textarea", "label": "Who else can take a night or a shift this week, and when we will ask:"}, {"id": "f5", "type": "textarea", "label": "After a week: hours each of us actually slept, and what we will change:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'planning']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('things-i-did-well-that-nobody-saw-this-week-sheet', 'Things I Did Well That Nobody Saw This Week Sheet', 'worksheet'::resource_kind, 'A weekly sheet for collecting the competent, kind or hard things the client did that no one witnessed or praised.', 'Use it to help a client who only counts what others notice start keeping their own record.', array['Adults', 'Teens']::text[], 'Ten minutes weekly, six weeks', 'Clients with low self-regard often run their worth on an external meter: if nobody saw it, it did not count. The sheet asks each week for things done well that no one witnessed: a hard call made, a mess cleaned, a temper held, a stranger helped, a task finished. Then it asks what each one says about the client, in their own words, and how it would feel to have someone else notice it. After six weeks the record is long. Review which categories fill up most; that is where the client''s actual character shows, unseen.', '[{"id": "f0", "type": "textarea", "label": "Something hard I did this week that nobody saw:"}, {"id": "f1", "type": "textarea", "label": "Something kind I did that nobody saw:"}, {"id": "f2", "type": "textarea", "label": "Something I finished or handled that nobody praised:"}, {"id": "f3", "type": "textarea", "label": "What each one says about who I am, in my words:"}, {"id": "f4", "type": "textarea", "label": "If someone had seen these, what might they have said?"}, {"id": "f5", "type": "textarea", "label": "After six weeks: which kinds of things fill the list most, and what that tells me:"}]'::jsonb, array['self-esteem', 'evidence log', 'strengths']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('needing-help-means-i-am-incompetent-belief-check-sheet', 'Needing Help Means I Am Incompetent Belief Check Sheet', 'cbt'::resource_kind, 'A belief check for the rule that needing help proves incompetence, applied to people the client respects, with a small ask planned.', 'Use it to help a client who will not ask for help examine the belief that keeps them stuck and alone.', array['Adults', 'Teens']::text[], '25 minutes', 'The belief that competent people do not need help keeps clients struggling alone and then hating themselves for struggling. The sheet writes the belief in their words, rates it, and then applies it to people they respect: do they ask for help, and does the client think less of them for it? It asks what the client has lost by not asking, and plans one small, specific request this week with a prediction of how the other person will respond. The outcome usually surprises them: people like being asked. The rewrite separates needing help from being incompetent.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words: if I need help with something, it means..."}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "People I respect who ask for help, and what I actually think of them for it:"}, {"id": "f3", "type": "textarea", "label": "What not asking has cost me this year (time, mistakes, loneliness):"}, {"id": "f4", "type": "textarea", "label": "One small, specific thing I will ask someone for this week, and my prediction of how they will react:"}, {"id": "f5", "type": "textarea", "label": "After: what happened, and how I would rewrite the belief now:"}]'::jsonb, array['self-esteem', 'core beliefs', 'behavioral experiment']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('rating-actions-not-selves-page', 'Rating Actions Not Selves Page', 'act'::resource_kind, 'A page that moves every self-rating of the day onto the action instead, so the person stays unrated and the behavior stays changeable.', 'Use it to help a client who grades themselves as a whole learn to grade what they did instead.', array['Adults', 'Teens']::text[], '15 minutes to set up, one week of entries', 'A global self-rating (I am useless) cannot be improved; a rated action (I put off that call) can. The page catches each self-rating of the day and translates it: what was the action, and what would a fair rating of the action be? The self stays out of it. Clients object that this is a trick; the response is that the trick is the other way around, since no action is big enough to grade a whole person. After a week they review what they rated most and what the actions have in common. The pattern in the actions is the work; the person was never the problem.', '[{"id": "f0", "type": "textarea", "label": "Today''s self-rating, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "The action it was about, described plainly:"}, {"id": "f2", "type": "textarea", "label": "A fair rating of the action alone, and what would make it better next time:"}, {"id": "f3", "type": "textarea", "label": "What I notice when the rating lands on the action instead of on me:"}, {"id": "f4", "type": "textarea", "label": "After a week: the self-ratings that came up most, and what the actions underneath had in common:"}]'::jsonb, array['self-esteem', 'self-as-context', 'defusion']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-shrinking-stand-tall-card', 'Opposite Action to Shrinking Stand Tall Card', 'dbt'::resource_kind, 'An opposite action card for shame''s urge to shrink: the posture, voice and eye contact to use in the moment of wanting to disappear.', 'Use it to help a client whose shame makes them physically smaller act opposite with the body first.', array['Adults', 'Teens']::text[], 'Five minutes per use', 'Shame that does not fit the facts tells the body to hide: shoulders in, voice down, eyes on the floor, leave early. Opposite action goes the other way with the body first, since the mind follows posture more than clients expect. The card has them describe their shrinking signature, then design the opposite: feet planted, shoulders back, chin level, voice at normal volume, eye contact held for a sentence, staying five more minutes. It asks where they will practice this week. Opposite action is for shame that does not fit; if the client acted against their values, repair is the move instead.', '[{"id": "f0", "type": "textarea", "label": "My shrinking signature: what my body does when shame hits:"}, {"id": "f1", "type": "textarea", "label": "Does the shame fit the facts? Did I act against my values, or do I just feel exposed?"}, {"id": "f2", "type": "textarea", "label": "If it does not fit, my opposite posture: feet, shoulders, chin, hands:"}, {"id": "f3", "type": "textarea", "label": "Voice and eyes: what volume, and how long I will hold eye contact:"}, {"id": "f4", "type": "textarea", "label": "Where I will practice this week, and how long I will stay past the urge to leave:"}, {"id": "f5", "type": "textarea", "label": "After: what my mind did when my body refused to shrink:"}]'::jsonb, array['self-esteem', 'opposite action', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('teach-the-group-a-tiny-skill-game', 'Teach the Group a Tiny Skill Game', 'game'::resource_kind, 'A group game where each player teaches one tiny skill in two minutes and notices what it feels like to be the one who knows.', 'Use it to let people who do not believe they are good at anything experience being the one who knows.', array['Adults', 'Teens', 'Groups']::text[], '40 minutes', 'Each player picks one tiny skill they can teach in two minutes: a card shuffle, a knot, a phrase in another language, a stretch, a way to fold a shirt. They teach it, the group tries it, and the teacher helps anyone stuck. After each turn the group names one thing the teacher did well as a teacher. The debrief asks each player what it felt like to be the one who knew and how long it took them to think of a skill (usually a long time, and that pause is the point). Keep turns strict so no one apologizes their way through.', '[{"id": "f0", "type": "textarea", "label": "The tiny skill I taught, and how long it took me to think of one:"}, {"id": "f1", "type": "textarea", "label": "What it felt like to be the one who knew something the group did not:"}, {"id": "f2", "type": "textarea", "label": "What the group said I did well as a teacher:"}, {"id": "f3", "type": "textarea", "label": "A skill someone else taught that I want to keep:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about the idea that I am not good at anything:"}]'::jsonb, array['self-esteem', 'game', 'strengths']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('group-chat-reply-delay-log', 'Group Chat Reply Delay Log', 'worksheet'::resource_kind, 'A log of group chat messages the client drafted, edited and delayed or deleted, with the time spent and what they finally sent.', 'Use it to make visible the hidden hours a socially anxious client spends composing and not sending.', array['Adults', 'Teens']::text[], 'One week', 'Group chats are a stage where the socially anxious client performs for an audience that is not watching. The log records each time they drafted a reply: how many edits, how long before sending, whether they deleted it, and what they imagined the group would think. It then records what happened when they did send (usually nothing, or a thumbs-up). After a week the total minutes are often startling. The second week adds a rule: send the first draft within two minutes, or do not reply at all; both are allowed. Review which was easier.', '[{"id": "f0", "type": "textarea", "label": "The message I was replying to, and what I drafted:"}, {"id": "f1", "type": "textarea", "label": "How many times I edited it, and how long before I sent or deleted it:"}, {"id": "f2", "type": "textarea", "label": "What I imagined the group would think:"}, {"id": "f3", "type": "textarea", "label": "What actually happened after I sent it, or after I stayed silent:"}, {"id": "f4", "type": "textarea", "label": "Total minutes spent on group chat replies this week:"}, {"id": "f5", "type": "textarea", "label": "Second week, with the two-minute rule: what changed, and what I notice about the replies I did not agonize over:"}]'::jsonb, array['social anxiety', 'avoidance', 'self-monitoring']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('nobody-said-goodbye-to-me-thought-record', 'Nobody Said Goodbye to Me Thought Record', 'cbt'::resource_kind, 'A thought record for the end of a gathering when the client leaves unnoticed and concludes they were not wanted there.', 'Use it to help a client examine the moment of leaving a gathering and what the lack of a goodbye actually means.', array['Adults', 'Teens']::text[], '15 minutes', 'The client slips out of a party or a meeting, no one says goodbye, and the ride home becomes a verdict: nobody noticed I was there. The record captures the exit (how they left, who was nearby, what was happening), the thought and the feeling, and then the evidence: did they say goodbye to anyone, how do people usually leave this kind of event, who did get a goodbye and why. It asks for the alternative explanation and a plan for the next exit, which usually involves the client saying goodbye first to one person. The experiment is the plan.', '[{"id": "f0", "type": "textarea", "label": "How I left: who was nearby, what was going on, whether I told anyone I was going:"}, {"id": "f1", "type": "textarea", "label": "The thought on the way home, and the feeling with it:"}, {"id": "f2", "type": "textarea", "label": "Did I say goodbye to anyone? How do people usually leave this kind of event?"}, {"id": "f3", "type": "textarea", "label": "Who did get a goodbye, and what was different about their exit?"}, {"id": "f4", "type": "textarea", "label": "An alternative explanation that fits the facts:"}, {"id": "f5", "type": "textarea", "label": "My plan for the next exit: who I will say goodbye to first, and what I will say:"}]'::jsonb, array['social anxiety', 'thought record', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('introducing-myself-with-shaky-hands-willingness-page', 'Introducing Myself With Shaky Hands Willingness Page', 'act'::resource_kind, 'A willingness page for the moment of introducing oneself in a new group, with the shaking allowed and the introduction made anyway.', 'Use it to help a client make introductions with the anxiety visible instead of waiting until it is hidden.', array['Adults', 'Teens']::text[], '15 minutes before, 10 after', 'Introductions are the gate the socially anxious client will not walk through until the hands stop shaking, which they do not. The page prepares one introduction: the setting, the name and one sentence the client will say, what their body will probably do, and the willingness to let it do that in view. Afterward they log what the body did, whether anyone commented, and what happened in the conversation that followed. Willingness here means the shaking is allowed to come along, not that it should be hidden better. Review the willingness rating before and after.', '[{"id": "f0", "type": "textarea", "label": "The setting where I will introduce myself, and when:"}, {"id": "f1", "type": "textarea", "label": "My name and the one sentence I will say after it:"}, {"id": "f2", "type": "textarea", "label": "What my body will probably do (hands, voice, face) and my willingness to let it, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "After: what my body actually did, and whether anyone said anything about it:"}, {"id": "f4", "type": "textarea", "label": "What happened in the conversation after the introduction:"}]'::jsonb, array['social anxiety', 'willingness', 'exposure']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('give-skills-at-the-work-happy-hour-card', 'GIVE Skills at the Work Happy Hour Card', 'dbt'::resource_kind, 'A GIVE card for the work social event: Gentle, Interested, Validate, Easy manner, planned for the first twenty minutes.', 'Use it to give a client who dreads work socials a relationship-keeping skill that does not require being interesting.', array['Adults']::text[], '15 minutes to plan', 'The work happy hour asks the socially anxious client to be witty, and they cannot, so they leave or do not go. GIVE asks something else: be gentle (no sarcasm about the event), be interested (ask and listen), validate (that does sound like a long week), use an easy manner (a half smile, a relaxed posture). None of it requires a good story. The card plans the first twenty minutes: who to stand near, two questions to ask, a validating line, and the exit if needed. Afterward the client reviews whether interested got them further than interesting would have.', '[{"id": "f0", "type": "textarea", "label": "Who I will stand near or sit beside first:"}, {"id": "f1", "type": "textarea", "label": "Two questions I will ask that show interest:"}, {"id": "f2", "type": "textarea", "label": "A validating line I can use when someone complains or shares something:"}, {"id": "f3", "type": "textarea", "label": "My easy manner: what my face, posture and hands will do:"}, {"id": "f4", "type": "textarea", "label": "How long I will stay, and my exit line:"}, {"id": "f5", "type": "textarea", "label": "After: did being interested work better than trying to be interesting?"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'skills']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('sleepover-brave-plan-drawing', 'Sleepover Brave Plan Drawing', 'kids'::resource_kind, 'A drawing activity where the child draws a sleepover from arrival to morning, marking the scary parts and a brave plan for each.', 'Use it to help a nervous child walk through a first sleepover in pictures before they live it.', array['Children']::text[], '30 minutes', 'The child draws the sleepover as a comic strip: arriving, dinner, games, getting ready for bed, lights out, waking up. At each panel they mark how brave it feels and draw or say what would help there (knowing where the bathroom is, a photo in the bag, the plan if they want to call). The parent writes their part in: the pickup call rule, what they will say on the phone, and that coming home early is allowed and not a failure. Coach the parent to practice the phone call on a calm day. The drawing goes in the bag.', '[{"id": "f0", "type": "textarea", "label": "Draw the sleepover as a comic strip, from arriving to morning:"}, {"id": "f1", "type": "textarea", "label": "Mark each picture: how brave it feels, 1 to 5:"}, {"id": "f2", "type": "textarea", "label": "For the scariest picture: what would help me there:"}, {"id": "f3", "type": "textarea", "label": "What goes in my bag that helps (a photo, a stuffed animal, my drawing):"}, {"id": "f4", "type": "textarea", "label": "Parent: our phone rule, what I will say if they call, and what happens if they want to come home:"}]'::jsonb, array['social anxiety', 'children', 'drawing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('pet-loss-routine-gaps-sheet', 'Pet Loss Routine Gaps Sheet', 'worksheet'::resource_kind, 'A sheet that maps the moments in the day that belonged to a pet who died, with what the client feels at each gap now.', 'Use it to help a client grieving an animal name the small daily absences that nobody else sees.', array['Adults', 'Teens']::text[], '25 minutes', 'Grief for a pet is often dismissed by others and then by the client, who feels foolish for the size of it. The sheet takes the day hour by hour and marks the moments that were the animal''s: the walk, the feeding, the greeting at the door, the weight on the bed. For each gap it asks what the client feels when the moment arrives and what, if anything, they want there now, a walk kept, a bowl put away, nothing yet. The point is to make the loss legible. Watch for a client who rushes to replace the routine; nothing yet is a fine answer for a while.', '[{"id": "f0", "type": "textarea", "label": "The moments in my day that belonged to them (walks, meals, the greeting, bedtime):"}, {"id": "f1", "type": "textarea", "label": "What I feel when each of those moments arrives now:"}, {"id": "f2", "type": "textarea", "label": "The gap that is hardest, and what makes it the hardest:"}, {"id": "f3", "type": "textarea", "label": "For each gap: keep the routine, let it go, or nothing yet:"}, {"id": "f4", "type": "textarea", "label": "Something I want to say about them that other people have not given me room to say:"}]'::jsonb, array['grief and loss', 'routines', 'pacing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('i-did-not-say-goodbye-properly-thought-check-sheet', 'I Did Not Say Goodbye Properly Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for guilt about the last conversation or a missed goodbye, with what the client knew at the time laid out.', 'Use it to help a grieving client examine the standard they are holding their last moments to.', array['Adults', 'Teens']::text[], '20 minutes', 'Many grieving clients carry a specific guilt about the last exchange: it was ordinary, or rushed, or they were not there. The sheet records the thought and its weight, then asks what the client knew at the time, what a proper goodbye would have needed (knowing it was the last), and what the person who died would say about the ordinary last conversation. It asks what the client''s many earlier goodbyes added up to. The rewrite does not remove the wish; it separates the wish for a different ending from the verdict that they failed. Go gently; this one often brings tears.', '[{"id": "f0", "type": "textarea", "label": "The last exchange, as I remember it, and the thought I have about it:"}, {"id": "f1", "type": "textarea", "label": "How heavy the guilt is, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What I knew at the time about how long we had:"}, {"id": "f3", "type": "textarea", "label": "What a proper goodbye would have required me to know:"}, {"id": "f4", "type": "textarea", "label": "What they would say about that last ordinary conversation:"}, {"id": "f5", "type": "textarea", "label": "The thousand earlier goodbyes: what they added up to, and a rewrite that keeps the wish and drops the verdict:"}]'::jsonb, array['grief and loss', 'thought record', 'guilt']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('setting-a-place-for-them-values-ritual-page', 'Setting a Place for Them Values Ritual Page', 'act'::resource_kind, 'A page for designing a small ritual that keeps the person present at a meal or gathering, built from the values they shared.', 'Use it to help a grieving client carry the relationship forward in action rather than only in absence.', array['Adults', 'Teens']::text[], '30 minutes', 'Grief is love with no one to hand it to, and a ritual gives it somewhere to go. The page asks what the person valued that the client values too, what they did together that expressed it, and what small, repeatable act could carry it: a chair at the table at holidays, their recipe cooked on a certain day, their toast given. The client chooses one and plans its first occasion, including what they will say if someone asks. Watch for rituals built to avoid the loss; the test is whether the ritual lets the client feel it and go on, rather than skip it.', '[{"id": "f0", "type": "textarea", "label": "What they valued that I value too:"}, {"id": "f1", "type": "textarea", "label": "Something we did together that expressed it:"}, {"id": "f2", "type": "textarea", "label": "Small, repeatable acts that could carry it forward (list several):"}, {"id": "f3", "type": "textarea", "label": "The one I will start with, and its first occasion:"}, {"id": "f4", "type": "textarea", "label": "What I will say if someone asks what I am doing, and who I want with me:"}, {"id": "f5", "type": "textarea", "label": "After the first time: what I felt, and whether I want to keep it:"}]'::jsonb, array['grief and loss', 'values', 'rituals']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('accepts-for-the-first-empty-evening-card', 'ACCEPTS for the First Empty Evening Card', 'dbt'::resource_kind, 'An ACCEPTS distraction card for the first evenings alone after a loss, with each letter filled in for the hours that used to be shared.', 'Use it to help a bereaved client get through the evening hours in the early weeks without numbing out or falling apart.', array['Adults', 'Teens']::text[], '15 minutes to build', 'The evenings are where the absence is loudest in the early weeks, and distraction is a legitimate skill for getting through them. ACCEPTS gives seven ways: Activities, Contributing, Comparisons, Emotions (something that brings a different one), Pushing away for now, Thoughts (counting, a puzzle), Sensations (a hot shower, cold air). The client fills each letter with something they could actually do between dinner and bed. Make clear that distraction is for getting through the hours, not for avoiding the grief; the grief gets its time in session and in the day. Review which letters worked.', '[{"id": "f0", "type": "textarea", "label": "Activities: two things I could do between dinner and bed:"}, {"id": "f1", "type": "textarea", "label": "Contributing: one small thing I could do for someone else this week:"}, {"id": "f2", "type": "textarea", "label": "Comparisons and Emotions: a show or music that brings a different feeling for an hour:"}, {"id": "f3", "type": "textarea", "label": "Pushing away for now: how I will set the grief down for an hour, and when I will pick it up:"}, {"id": "f4", "type": "textarea", "label": "Thoughts and Sensations: a puzzle, a count, a hot shower, cold air; what works for me:"}, {"id": "f5", "type": "textarea", "label": "After a week of evenings: which letters helped, and which hours were still the worst:"}]'::jsonb, array['grief and loss', 'distress tolerance', 'skills']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('paper-memory-lantern-craft', 'Paper Memory Lantern Craft', 'kids'::resource_kind, 'A craft where the child decorates a paper lantern with memories of the person or pet who died and the parent adds a battery light.', 'Use it to give a grieving child something to make with their hands that holds the memories and can be lit on hard nights.', array['Children']::text[], '45 minutes', 'The child covers a paper lantern or a jar with drawings and words: the person''s face, something they did together, their favorite things. The parent helps with the hard parts and adds a battery candle, never a flame. Together they choose when it gets lit: the first week every night, then on the nights the child asks, or on special dates. The lantern lives somewhere the child can reach. Coach the parent to let the child talk while they draw, to answer questions plainly, and not to tidy the drawings. Making it is the conversation.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe what will go on my lantern:"}, {"id": "f1", "type": "textarea", "label": "A memory I want on it that other people might not know about:"}, {"id": "f2", "type": "textarea", "label": "When we will light it, and who turns it on:"}, {"id": "f3", "type": "textarea", "label": "Where it will live so I can get to it:"}, {"id": "f4", "type": "textarea", "label": "Parent: a question my child asked while we made it, and how I answered:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('breakup-contact-decision-sheet', 'Breakup Contact Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for contact with an ex: what each kind of contact gives, what it costs, and the rules the client sets for the next month.', 'Use it to help a client after a breakup decide about contact on purpose instead of at midnight.', array['Adults', 'Teens']::text[], '30 minutes', 'Contact after a breakup is usually decided at the worst moments, late and lonely, and regretted by morning. The sheet lists each kind of contact (texting, calling, following their accounts, mutual friends, returning belongings), what each one gives the client and what it costs them the next day, and what they are hoping will happen if they reach out. Then the client sets rules for one month: what is allowed, what is not, and who they will text instead at midnight. The rules can be revised in a month in daylight. Watch for hope of reconciliation hidden inside logistics.', '[{"id": "f0", "type": "textarea", "label": "The kinds of contact still happening or tempting me (texts, calls, following, mutual friends, belongings):"}, {"id": "f1", "type": "textarea", "label": "For each: what it gives me in the moment, and what it costs me the next day:"}, {"id": "f2", "type": "textarea", "label": "What I am hoping will happen when I reach out, honestly:"}, {"id": "f3", "type": "textarea", "label": "My rules for the next month: allowed, not allowed:"}, {"id": "f4", "type": "textarea", "label": "Who I will text instead at midnight, and what I will say:"}, {"id": "f5", "type": "textarea", "label": "At the end of the month: what held, what slipped, and what I want the rules to be now:"}]'::jsonb, array['relationship issues', 'decisions', 'boundaries']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('my-friend-is-mad-at-me-evidence-check-sheet', 'My Friend Is Mad at Me Evidence Check Sheet', 'cbt'::resource_kind, 'An evidence check for the fear that a friend is angry, separating observed signs from the mind''s additions, with a direct question planned.', 'Use it to help a client who assumes friends are upset with them check the signs and then ask instead of withdrawing.', array['Adults', 'Teens']::text[], '15 minutes', 'The friend replied briefly, did not laugh, left early, and the client concludes they are angry and pulls back, which produces the distance they feared. The sheet separates what was observed from what was inferred, lists the other explanations (tired, distracted, their own bad week), rates the fear before and after, and plans the direct question that the client is avoiding: hey, are we okay, you seemed quiet. Review what happened when they asked. Most friends were not angry; the few who were usually appreciated being asked. Either way, asking beats withdrawing.', '[{"id": "f0", "type": "textarea", "label": "What I actually observed my friend do or say:"}, {"id": "f1", "type": "textarea", "label": "What I added to it (they are angry, they are done with me):"}, {"id": "f2", "type": "textarea", "label": "How strongly I believe they are angry, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Other explanations for what I observed:"}, {"id": "f4", "type": "textarea", "label": "The direct question I will ask, word for word, and when:"}, {"id": "f5", "type": "textarea", "label": "After I asked: what they said, and what I would have done without asking:"}]'::jsonb, array['relationship issues', 'evidence', 'thought record']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('family-group-chat-hooks-noticing-page', 'Family Group Chat Hooks Noticing Page', 'act'::resource_kind, 'A noticing page for the family group chat: the messages that hook the client, the urge each brings, and the choice to reply from values.', 'Use it to help a client stay in the family chat without being pulled into every old argument it carries.', array['Adults', 'Teens']::text[], 'One week of noticing', 'The family group chat is a hook factory: a sibling''s comment, a parent''s forwarded article, a photo that was not sent to the client. The page has the client log each hook this week: the message, the thought and feeling it pulled, the urge (reply sharply, leave the chat, go silent for a week), and whether they got hooked. Then it asks what kind of family member they want to be in the chat and what a reply from that place would say. Leaving the chat can be a valued choice too, made in daylight rather than in a flash.', '[{"id": "f0", "type": "textarea", "label": "This week''s hooks: the message and who sent it:"}, {"id": "f1", "type": "textarea", "label": "The thought and feeling each one pulled, and the urge that came with it:"}, {"id": "f2", "type": "textarea", "label": "Whether I got hooked, and what I did:"}, {"id": "f3", "type": "textarea", "label": "The kind of family member I want to be in this chat, in a few words:"}, {"id": "f4", "type": "textarea", "label": "A reply from that place to the biggest hook of the week, or the choice not to reply, and how it would feel:"}]'::jsonb, array['relationship issues', 'defusion', 'family']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('validate-before-fixing-card-for-friends', 'Validate Before Fixing Card for Friends', 'dbt'::resource_kind, 'A card for the friend who brings a problem, with the validating line that comes first and the question that asks whether they want ideas.', 'Use it to help a client who jumps to solutions learn to validate first and offer fixes only when asked.', array['Adults', 'Teens']::text[], '10 minutes to build, use as needed', 'The client''s friends complain that talking to them feels like being handed a to-do list. The card builds a two-step habit: first a validating line that shows the friend''s reaction makes sense (that sounds exhausting, no wonder you are upset), then a question (do you want ideas or do you want to vent). The client writes three validating lines in their own voice and practices them aloud. Then they log the next three conversations: did they validate first, what did the friend choose, and what happened. Most friends choose to vent, and most clients are surprised the conversation went better.', '[{"id": "f0", "type": "textarea", "label": "Three validating lines in my own voice, for when a friend brings me a problem:"}, {"id": "f1", "type": "textarea", "label": "The question I will ask before offering any idea:"}, {"id": "f2", "type": "textarea", "label": "Conversation one: did I validate first, what did they choose, and how did it go?"}, {"id": "f3", "type": "textarea", "label": "Conversation two: did I validate first, what did they choose, and how did it go?"}, {"id": "f4", "type": "textarea", "label": "Conversation three: did I validate first, what did they choose, and how did it go?"}, {"id": "f5", "type": "textarea", "label": "What I notice about conversations where I waited to be asked:"}]'::jsonb, array['relationship issues', 'validation', 'interpersonal effectiveness']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('questions-after-a-betrayal-pacing-agreement-for-partners', 'Questions After a Betrayal Pacing Agreement for Partners', 'couples'::resource_kind, 'An agreement on when and how the hurt partner''s questions after a betrayal get asked and answered, so they stop running the day.', 'Use it to help a couple rebuilding after a betrayal contain the questions to a time both can bear.', array['Couples']::text[], '45 minutes', 'After a betrayal the hurt partner has questions at all hours, and the partner who caused the hurt either answers everything, which feeds the loop, or shuts down, which reads as hiding. The agreement sets a time for questions each day or several times a week, a length, a place, and the rule that outside that time questions are written down and brought to the slot. The partner who caused the hurt agrees to answer honestly in the slot and to say when they do not know. Both agree what happens if a question is about details that only wound. Review weekly; the slot shrinks as trust grows.', '[{"id": "f0", "type": "textarea", "label": "Hurt partner: what the questions do for me, and what asking them at all hours costs me:"}, {"id": "f1", "type": "textarea", "label": "Partner who caused the hurt: what it is like to be asked at all hours, and what I am afraid of when I answer:"}, {"id": "f2", "type": "textarea", "label": "Our question time: when, how long, where:"}, {"id": "f3", "type": "textarea", "label": "What happens with a question that comes outside the slot:"}, {"id": "f4", "type": "textarea", "label": "Our rule for a question whose answer would only wound, and who decides:"}, {"id": "f5", "type": "textarea", "label": "After a week: how the slot went, and whether we want to change its length or frequency:"}]'::jsonb, array['relationship issues', 'couples', 'repair', 'pacing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('dating-again-pacing-steps-sheet', 'Dating Again Pacing Steps Sheet', 'worksheet'::resource_kind, 'A pacing sheet for a survivor thinking about dating again, with each step set at their speed and the exits built in.', 'Use it to help a client return to dating on their own timeline with safety and pacing planned rather than improvised.', array['Adults']::text[], '30 minutes', 'Dating again after sexual abuse is a series of steps, and most clients either rush it to prove something or avoid it entirely. The sheet lays out the steps the client wants (a profile, messaging, a video call, a short daytime meeting in public) and lets them set the pace for each, with the rule that any step can be repeated or paused. It plans the exits: how they leave a meeting that feels wrong, who knows where they are, and what they will tell themselves if they leave early. Nothing here asks about the past. It is about the pace of the future.', '[{"id": "f0", "type": "textarea", "label": "The steps I want, in order, from first to furthest I am ready to plan:"}, {"id": "f1", "type": "textarea", "label": "How long I want to stay at each step before deciding on the next:"}, {"id": "f2", "type": "textarea", "label": "My exit plan for a meeting that feels wrong: what I say, where I go, who I text:"}, {"id": "f3", "type": "textarea", "label": "Who will know where I am and when I will check in:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if I pause or go back a step:"}, {"id": "f5", "type": "textarea", "label": "The one step I am ready for this month, and when:"}]'::jsonb, array['sexual abuse', 'pacing', 'safety']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('freezing-was-my-body-protecting-me-gentle-check-sheet', 'Freezing Was My Body Protecting Me Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle check sheet for self-blame about freezing, with what the body does under threat and what the client would tell a friend.', 'Use it to help a survivor hold the fact that they froze without the verdict that they failed.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'I should have fought is one of the heaviest thoughts survivors carry. The sheet does not ask for the details of what happened; it asks for the thought and its weight, what the client knows about what bodies do under overwhelming threat (freezing is one of the body''s built-in responses, not a choice), and what they would say to a friend who told them they froze. Then it asks what the freeze may have protected them from. Complete it in session, not as homework, and go slowly. The rewrite keeps the grief for what happened and drops the blame for the body''s response.', '[{"id": "f0", "type": "textarea", "label": "The thought about freezing or not fighting back, in my words, and its weight 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "What I know about what a body does when it is overwhelmed by threat:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who told me they froze:"}, {"id": "f3", "type": "textarea", "label": "What freezing may have protected me from:"}, {"id": "f4", "type": "textarea", "label": "A rewrite that keeps the grief and drops the blame:"}]'::jsonb, array['sexual abuse', 'self-blame', 'stabilizing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('dropped-hobby-values-return-page', 'Dropped Hobby Values Return Page', 'act'::resource_kind, 'A page for the activity the client stopped after the abuse, with the value it carried and a small, paced step back toward it.', 'Use it to help a survivor reclaim something they loved at a pace they choose.', array['Adults', 'Teens']::text[], '25 minutes', 'Survivors often drop activities that were theirs, a sport, a choir, a class, because of where they happened or who was there, and the loss goes unnamed. The page asks what was dropped, what it gave the client that nothing has replaced, and what value it expressed. Then it asks what a small return could look like: a different venue, a different group, a version done alone first. The client sets the pace and the step. Nothing here asks why it was dropped in detail. If the return is not wanted, naming the loss is still the work.', '[{"id": "f0", "type": "textarea", "label": "Something I loved doing that I stopped:"}, {"id": "f1", "type": "textarea", "label": "What it gave me that nothing has replaced:"}, {"id": "f2", "type": "textarea", "label": "The value it expressed, in my words:"}, {"id": "f3", "type": "textarea", "label": "What a small return could look like, in a different place or a different form:"}, {"id": "f4", "type": "textarea", "label": "The pace I want, and the first step if I want one:"}, {"id": "f5", "type": "textarea", "label": "Who I would want to know I am trying, and who I would not:"}]'::jsonb, array['sexual abuse', 'values', 'pacing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('self-soothe-playlist-for-after-appointments-card', 'Self-Soothe Playlist for After Appointments Card', 'dbt'::resource_kind, 'A card for building a short playlist and a two-sense soothing routine for the way home after an appointment that stirs things up.', 'Use it to give a survivor a planned way to settle after appointments that stir things up, so the rest of the day is theirs.', array['Adults', 'Teens']::text[], '15 minutes to build', 'Appointments that touch the abuse, a medical exam, a legal meeting, a hard session, leave the client raw for hours. The card builds a routine for the first thirty minutes afterward: a playlist of four or five songs that settle rather than stir, something to hold or smell in the bag, and where they will go first (not straight into work or parenting if it can be helped). The client decides who they will text to say I am out, and what they will not do (drive fast, go over it again). Review after the next appointment and adjust the songs.', '[{"id": "f0", "type": "textarea", "label": "Four or five songs that settle me, in order:"}, {"id": "f1", "type": "textarea", "label": "What I will carry to hold or smell on the way out:"}, {"id": "f2", "type": "textarea", "label": "Where I will go first after the appointment, and for how long:"}, {"id": "f3", "type": "textarea", "label": "Who I will text to say I am out, and what I will say:"}, {"id": "f4", "type": "textarea", "label": "What I will not do in the first thirty minutes:"}, {"id": "f5", "type": "textarea", "label": "After the next appointment: what worked, and what I will change:"}]'::jsonb, array['sexual abuse', 'self-soothing', 'distress tolerance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('swimsuit-rule-private-parts-drawing-activity', 'Swimsuit Rule Private Parts Drawing Activity', 'kids'::resource_kind, 'A drawing activity where the child colors a swimsuit onto a body outline and learns the rule about private parts, with the parent''s words.', 'Use it to teach a child the swimsuit rule for private parts in a plain, calm way that the parent can repeat at home.', array['Children']::text[], '20 minutes', 'The child colors a swimsuit onto a simple body outline and learns the rule: the parts a swimsuit covers are private, nobody touches them except to keep you clean or healthy with a parent knowing, and no one asks you to touch theirs. The child names the grown-ups they would tell if someone broke the rule. The parent practices saying the rule in plain words and agrees to repeat it at bath time. Use the body''s plain names. If a child discloses anything during this activity, follow your reporting duties and stop the activity to attend to the child.', '[{"id": "f0", "type": "textarea", "label": "Color the swimsuit onto the body picture:"}, {"id": "f1", "type": "textarea", "label": "The rule in my own words: the parts my swimsuit covers are..."}, {"id": "f2", "type": "textarea", "label": "Who is allowed to help with those parts, and when:"}, {"id": "f3", "type": "textarea", "label": "The grown-ups I would tell if someone broke the rule:"}, {"id": "f4", "type": "textarea", "label": "Parent: the words I will use to repeat the rule at home, and when I will say it:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('skills-that-fit-in-a-work-bathroom-break-card', 'Skills That Fit in a Work Bathroom Break Card', 'worksheet'::resource_kind, 'A card of coping skills that take under three minutes and fit in a bathroom stall at work, with the one the client will reach for first.', 'Use it to give a client who has no private space at work a set of skills that work in the one room they can lock.', array['Adults']::text[], '15 minutes', 'Many clients have good skills and nowhere at work to use them. The bathroom is the one lockable room, and the card builds a menu for it: cold water on the wrists, a wall push with the hands, a long exhale count, a text to one person, a phrase on a card in the wallet, a stretch. Each skill gets a time estimate and a rating after the first try. The client picks a default so there is no deciding in the moment. Review which skill traveled from the stall back to the desk. Keep it discreet; the point is not to be seen using a skill.', '[{"id": "f0", "type": "textarea", "label": "Skills I could do in a locked bathroom stall in under three minutes:"}, {"id": "f1", "type": "textarea", "label": "The one I will reach for first, by default:"}, {"id": "f2", "type": "textarea", "label": "How each one went on its first try, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "The sign at my desk that tells me it is time for a break:"}, {"id": "f4", "type": "textarea", "label": "After a week: which skill traveled best from the stall back to my desk:"}]'::jsonb, array['coping skills', 'skills', 'self-soothing']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('coping-skill-did-not-work-so-i-am-hopeless-thought-check', 'Coping Skill Did Not Work So I Am Hopeless Thought Check', 'cbt'::resource_kind, 'A thought check for the conclusion drawn when a skill fails once, with the specifics of the attempt and what one failed try shows.', 'Use it to help a client separate a skill that did not fit a moment from the verdict that nothing will ever help.', array['Adults', 'Teens']::text[], '15 minutes', 'A skill fails once and the client concludes they are beyond help. The sheet records the attempt in detail: the skill, the situation, how intense the distress was, how long the skill was tried, and how the client expected it to work. Then it asks what a single failed attempt can and cannot show, what a coach would say about one bad practice, and what would be a fair conclusion (wrong skill for that intensity, tried for ten seconds, expected it to erase the feeling). The rewrite is specific. Hopeless is a conclusion about the self; the data is about one try.', '[{"id": "f0", "type": "textarea", "label": "The skill, the situation, and how intense the distress was, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "How long I tried it, and what I expected it to do:"}, {"id": "f2", "type": "textarea", "label": "The conclusion I drew about myself:"}, {"id": "f3", "type": "textarea", "label": "What one failed attempt can show, and what it cannot:"}, {"id": "f4", "type": "textarea", "label": "A fair conclusion about the attempt, specific to the skill and the moment:"}, {"id": "f5", "type": "textarea", "label": "What I will try differently next time (a different skill for that intensity, longer, a different expectation):"}]'::jsonb, array['coping skills', 'thought record', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('willingness-as-a-coping-skill-page', 'Willingness as a Coping Skill Page', 'act'::resource_kind, 'A page that adds willingness to the client''s coping menu: for feelings no skill can remove, the skill of making room and acting anyway.', 'Use it to help a client who has run out of skills see that making room is also a skill, and practice it on one feeling.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients collect coping skills to make feelings go away, and some feelings do not go. The page introduces willingness as a skill in its own right: noticing the feeling, giving it space in the body, and doing the next valued thing with it present. The client picks one recurring feeling that their skills have not removed, describes what fighting it costs, and plans one situation this week to practice making room instead. The log records what the feeling did when it was not fought. Willingness is not giving up; it is choosing where the energy goes.', '[{"id": "f0", "type": "textarea", "label": "A feeling my coping skills have not been able to remove:"}, {"id": "f1", "type": "textarea", "label": "What fighting it costs me each time:"}, {"id": "f2", "type": "textarea", "label": "What making room for it would look like in the body (where I let it sit, what I stop doing):"}, {"id": "f3", "type": "textarea", "label": "One situation this week where I will practice willingness instead of a removal skill:"}, {"id": "f4", "type": "textarea", "label": "After: what the feeling did when I stopped fighting it, and what I did while it was there:"}]'::jsonb, array['coping skills', 'willingness', 'acceptance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('all-in-participate-skill-card', 'All-In Participate Skill Card', 'dbt'::resource_kind, 'A participate card for throwing oneself completely into a coping activity instead of doing it halfway while watching whether it works.', 'Use it to help a client whose skills fail because they use them with one eye on the distress learn to go all in.', array['Adults', 'Teens']::text[], '10 minutes to plan, use as needed', 'A skill done with half the attention, while the other half checks whether the distress is dropping, rarely works. The participate card asks the client to pick one activity and do it fully: if it is a walk, notice the feet and the air and nothing else; if it is music, sing. The card names the signs they are only half in (checking the time, rating the feeling, planning the next skill), and a cue to throw themselves back in. Set a time for the activity so they do not have to decide when it is done. Review the difference between the all-in version and the usual version.', '[{"id": "f0", "type": "textarea", "label": "The coping activity I will go all in on:"}, {"id": "f1", "type": "textarea", "label": "How I know I am only half in (checking, rating, planning the next thing):"}, {"id": "f2", "type": "textarea", "label": "My cue for throwing myself back in:"}, {"id": "f3", "type": "textarea", "label": "How long I will do it, decided in advance:"}, {"id": "f4", "type": "textarea", "label": "After: how the all-in version compared to how I usually do it:"}]'::jsonb, array['coping skills', 'mindfulness', 'core DBT']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('coping-skill-draft-pick-team-game', 'Coping Skill Draft Pick Team Game', 'game'::resource_kind, 'A team game where groups draft coping skills from a shared pool for a set of scenarios, defend their picks, and trade in the debrief.', 'Use it to get a group arguing about which skills fit which moments and leaving with a sharper menu.', array['Adults', 'Teens', 'Groups']::text[], '35 minutes', 'Write twenty skills on cards and six scenarios on bigger cards (a panic surge in a store, an urge at ten at night, a fight with a parent, a boring afternoon alone, a sleepless night, bad news by text). Teams take turns drafting one skill card at a time from the pool until the pool is empty. Then each team assigns their skills to scenarios and defends the matches to the group; the group votes on the best fit per scenario. Trades are allowed in the last round. The debrief asks which skill went undrafted and why, and which match surprised them. Everyone keeps a photo of the final board.', '[{"id": "f0", "type": "textarea", "label": "The skills my team drafted, in order, and why we picked our first one:"}, {"id": "f1", "type": "textarea", "label": "Our best match of a skill to a scenario, and how we defended it:"}, {"id": "f2", "type": "textarea", "label": "A skill nobody drafted, and why I think it was left:"}, {"id": "f3", "type": "textarea", "label": "A match from another team that I would use myself:"}, {"id": "f4", "type": "textarea", "label": "My own six-scenario menu, one skill each, taken from the board:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('tunnel-drive-step-plan-sheet', 'Tunnel Drive Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for driving through a tunnel, from photos to the full length, with a fear rating for each step and the first one chosen.', 'Use it to help a client who detours around every tunnel build the steps back to driving through one.', array['Adults']::text[], '25 minutes to plan, several weeks to run', 'Tunnel fear is often about being trapped with no exit, and the detours can add an hour to a commute. The sheet builds a step list: photos, videos from a driver''s view, sitting as a passenger through a short tunnel, driving a short one in light traffic, a longer one, rush hour. Each step gets a fear rating and the client orders them. For each step they name what they predict will happen and what they will do with their hands and breath. Repeat a step until the rating drops before moving on. Review the predictions against the outcomes.', '[{"id": "f0", "type": "textarea", "label": "Tunnels I avoid, and the detours they cost me each week:"}, {"id": "f1", "type": "textarea", "label": "My steps, from easiest to hardest, each with a fear rating 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "For my first step: what I predict will happen, and what I will do with my hands and breath:"}, {"id": "f3", "type": "textarea", "label": "After the first step: what actually happened, and the rating now:"}, {"id": "f4", "type": "textarea", "label": "When I will repeat it, and what tells me I am ready for the next step:"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('fear-of-vomiting-probability-check-sheet', 'Fear of Vomiting Probability Check Sheet', 'cbt'::resource_kind, 'A probability check for the fear of vomiting in public, with the client''s actual history against the odds they assign.', 'Use it to help a client whose life is organized around not vomiting look at how often it has actually happened.', array['Adults', 'Teens']::text[], '20 minutes', 'A fear of vomiting runs quietly under many avoidances: restaurants, travel, crowds, other people''s illness. The sheet asks how many times the client has vomited in the last ten years, how many of those were in public, and what they estimate the odds are on any given day; then it compares the estimate to the record. It lists the safety behaviors (carrying bags, sitting by exits, checking for illness) and what each one costs. The point is not that it could never happen; it is that the client is paying daily for something that has happened a handful of times. Avoid any discussion of eating rules.', '[{"id": "f0", "type": "textarea", "label": "Times I have actually vomited in the last ten years, and how many were in public:"}, {"id": "f1", "type": "textarea", "label": "The odds I assign to it happening on an ordinary day, as a percentage:"}, {"id": "f2", "type": "textarea", "label": "What the record says the odds actually are, roughly:"}, {"id": "f3", "type": "textarea", "label": "The things I do every day to prevent it (bags, exits, checking who is sick, leaving early):"}, {"id": "f4", "type": "textarea", "label": "What those things cost me in a week:"}, {"id": "f5", "type": "textarea", "label": "One safety behavior I will drop this week, and what I predict will happen:"}]'::jsonb, array['phobias', 'predictions', 'safety behaviors']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-shudder-page', 'Making Room for the Shudder Page', 'act'::resource_kind, 'A willingness page for the full-body shudder that disgust-based fears bring, allowed to run its course at a chosen distance.', 'Use it to help a client with a disgust-heavy fear let the shudder happen without it deciding what they do next.', array['Adults', 'Teens']::text[], '15 minutes per practice', 'Fears of insects, mice, mold, or needles often run on disgust more than danger, and the shudder is what the client is actually avoiding. The page sets a practice: the feared thing at a distance the client chooses (a photo, a video, a jar across the room), attention on the shudder as a body event with a start and a finish, and a timer for how long it lasts when allowed. The client rates willingness before and after and notes what the shudder did when nothing was done about it. Shudders that are allowed finish; shudders that are fought get stuck. Move the distance only when the client chooses.', '[{"id": "f0", "type": "textarea", "label": "The feared thing, and the distance I am choosing for this practice:"}, {"id": "f1", "type": "textarea", "label": "Where the shudder starts in my body and where it goes:"}, {"id": "f2", "type": "textarea", "label": "How long it lasted when I let it run, in seconds:"}, {"id": "f3", "type": "textarea", "label": "What my mind said during it, and what I did not do:"}, {"id": "f4", "type": "textarea", "label": "Willingness before and after, 0 to 10, and whether I want to change the distance next time:"}]'::jsonb, array['phobias', 'willingness', 'acceptance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('paced-breathing-at-the-pool-edge-step-card', 'Paced Breathing at the Pool Edge Step Card', 'dbt'::resource_kind, 'A paced breathing card for a fear of water, used on the pool edge with feet in and a step planned for the next visit.', 'Use it to give a client afraid of water a breathing skill tied to a specific place and a small step they control.', array['Adults', 'Teens']::text[], '20 minutes per visit', 'Water fear keeps clients off beaches and out of family swims for decades. The card pairs paced breathing (exhale longer than inhale, about six breaths a minute) with a fixed place: sitting on the pool edge with feet in the water, for ten minutes, breathing. Nothing else is required on the first visit. The card asks for the fear rating at the start, at five minutes and at ten, and the step for the next visit, which the client chooses (standing in the shallow end, holding the edge, a float). A trusted person in the water nearby helps and should be named. The client sets the pace of every step.', '[{"id": "f0", "type": "textarea", "label": "My breath count (in for, out for), and how I will keep time:"}, {"id": "f1", "type": "textarea", "label": "Fear at the start, at five minutes and at ten, sitting on the edge with my feet in:"}, {"id": "f2", "type": "textarea", "label": "Who was nearby in the water, and what I asked them to do and not do:"}, {"id": "f3", "type": "textarea", "label": "What my mind said at the edge, and what my body did:"}, {"id": "f4", "type": "textarea", "label": "My step for the next visit, chosen by me:"}]'::jsonb, array['phobias', 'breathing', 'TIPP']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('spot-the-spider-picture-hunt-game', 'Spot the Spider Picture Hunt Game', 'game'::resource_kind, 'A group game sorting a pile of photos by whether a small spider hides in them, with the shudder scored and the pile getting closer.', 'Use it to let a group practice looking at a feared creature in photos with the laughter and the competition carrying them through.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Print thirty photos of ordinary scenes, ten of which include a small spider somewhere. Players race to sort the pile into spider and no spider; speed and accuracy score points, and each player calls out their shudder rating after the round. Round two uses photos where the spiders are bigger or closer; round three lets players choose their own pile. Nobody is required to go up a round. The debrief asks what the shudder did between rounds and who surprised themselves. For clients with other feared creatures, swap the photos. Keep the game pace brisk; hesitation is where the fear builds.', '[{"id": "f0", "type": "textarea", "label": "My shudder rating after rounds one, two and three, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "How many I sorted right, and whether looking got easier or harder with speed:"}, {"id": "f2", "type": "textarea", "label": "What my mind said when I found one:"}, {"id": "f3", "type": "textarea", "label": "Whether I chose to go up a round, and why:"}, {"id": "f4", "type": "textarea", "label": "Something about the photos that surprised me:"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('selfie-retake-count-log', 'Selfie Retake Count Log', 'worksheet'::resource_kind, 'A log of each selfie session: shots taken, shots deleted, minutes spent, and what was wrong with the deleted ones in the client''s words.', 'Use it to make the hidden retake habit visible and show the client the minutes and the verdicts it is made of.', array['Teens', 'Adults']::text[], 'One week', 'Retaking a selfie forty times is a checking ritual that happens in private, and most clients have no idea of the count. The log records each session: the number of shots, the number deleted, the minutes spent, and the reason each deletion was made, in the client''s words. It also notes the mood before and after. At the end of the week they total the minutes and read the deletion reasons back as a list. The reasons are usually the same two or three verdicts over and over. The second week adds a rule the client chooses: a cap on shots or a first-take-only day.', '[{"id": "f0", "type": "textarea", "label": "Today''s session: how many shots, how many deleted, how many minutes:"}, {"id": "f1", "type": "textarea", "label": "What was wrong with the deleted ones, in my words:"}, {"id": "f2", "type": "textarea", "label": "Mood before and after, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "Total minutes this week, and the deletion reasons read back as a list:"}, {"id": "f4", "type": "textarea", "label": "The verdicts that repeat, and whose voice they are in:"}, {"id": "f5", "type": "textarea", "label": "My rule for next week (a cap, a first-take day), chosen by me:"}]'::jsonb, array['body image', 'self-monitoring', 'habits']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('old-photo-verdict-thought-record', 'Old Photo Verdict Thought Record', 'cbt'::resource_kind, 'A thought record for looking at an old photo of oneself and passing a verdict on the body then or now, with the thought caught and checked.', 'Use it to help a client catch the comparison that happens when they see a photo of their past self.', array['Teens', 'Adults']::text[], '15 minutes', 'An old photo appears in a feed or a drawer and the client passes a sentence: I looked better then, or I cannot believe I went out like that. The record catches the photo, the verdict, the feeling, and then asks what the client remembers about how they felt about their body at the time the photo was taken (usually just as critical), what they were doing in the photo, and who was there. The comparison between then and now is checked against the fact that the verdict was running then too. The rewrite moves from how the body looked to what the person was living.', '[{"id": "f0", "type": "textarea", "label": "The photo: when, where, and what I was doing in it:"}, {"id": "f1", "type": "textarea", "label": "The verdict I passed, in its exact words, and the feeling with it:"}, {"id": "f2", "type": "textarea", "label": "How I felt about my body at the time the photo was taken:"}, {"id": "f3", "type": "textarea", "label": "What I was living in that photo: who was there, what mattered that day:"}, {"id": "f4", "type": "textarea", "label": "What the then-versus-now comparison leaves out:"}, {"id": "f5", "type": "textarea", "label": "A rewrite that stays with the life in the photo instead of the body:"}]'::jsonb, array['body image', 'thought record', 'thinking traps']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('gym-locker-room-willingness-page', 'Gym Locker Room Willingness Page', 'act'::resource_kind, 'A willingness page for the locker room: the appearance thoughts expected, and the valued reason for being at the gym at all.', 'Use it to help a client who skips the gym because of the locker room go for their own reasons with the thoughts along for the ride.', array['Teens', 'Adults']::text[], '15 minutes before, 10 after', 'The locker room is where appearance thoughts are loudest, and many clients skip the activity they want because of the five minutes before it. The page names why the client wants to be at the gym (strength, a sport, a friend, feeling capable), none of which is about appearance, then lists the thoughts the locker room will bring and rates willingness to have them there. It plans where attention goes (the bag, the shoes, the music) and how long the client will spend in the room. Afterward: what the thoughts did and whether the workout happened. Nothing about the body gets measured or judged here.', '[{"id": "f0", "type": "textarea", "label": "Why I want to be at the gym, in words that have nothing to do with how I look:"}, {"id": "f1", "type": "textarea", "label": "The thoughts the locker room will probably bring:"}, {"id": "f2", "type": "textarea", "label": "My willingness to have those thoughts in that room, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "Where my attention will go while I change, and how long I will be in there:"}, {"id": "f4", "type": "textarea", "label": "After: what the thoughts did, and whether I did the thing I came for:"}]'::jsonb, array['body image', 'willingness', 'avoidance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-in-front-of-the-mirror-card', 'Nonjudgmental Stance in Front of the Mirror Card', 'dbt'::resource_kind, 'A card for describing what the mirror shows in neutral words only, no evaluations, for two minutes a day.', 'Use it to help a client replace the mirror''s verdicts with description and notice the difference in how they leave the room.', array['Teens', 'Adults']::text[], 'Two minutes daily, two weeks', 'The mirror is where judgments are fastest. The card practices the DBT nonjudgmental stance there: two minutes describing only what can be seen in neutral terms (a blue shirt, brown hair, a face, two arms) and catching each evaluation as it comes (that is a judgment) without replacing it with a compliment, which is just another judgment. The client logs how many judgments came up and what the two minutes felt like compared with a usual mirror visit. Nothing is measured, compared or fixed. The skill is in the catching, not in liking what is there.', '[{"id": "f0", "type": "textarea", "label": "My neutral description today, in plain words, no evaluations:"}, {"id": "f1", "type": "textarea", "label": "Judgments that came up, and how many I caught:"}, {"id": "f2", "type": "textarea", "label": "What the two minutes felt like compared with how I usually leave the mirror:"}, {"id": "f3", "type": "textarea", "label": "Whether I tried to replace a judgment with a compliment, and what I notice about that:"}, {"id": "f4", "type": "textarea", "label": "After two weeks: has the number of judgments changed, and how do I leave the room now?"}]'::jsonb, array['body image', 'mindfulness', 'nonjudgmental']::text[], '2026-11-16T15:00:00+00:00'::timestamptz),
  ('changing-bodies-over-the-years-talk-sheet-for-partners', 'Changing Bodies Over the Years Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for long-term partners whose bodies have changed, with what each fears the other thinks and what each actually values.', 'Use it to help a long-term couple replace assumptions about each other''s view of their changing bodies with the real thing.', array['Couples']::text[], '40 minutes', 'In a long relationship both bodies change, and each partner often assumes the other is quietly disappointed. Neither says it; both act on it, with less touch and more covering up. The sheet has each partner write what they fear the other thinks about their body now, then what they actually notice and value about their partner''s body and presence, with no grading, no comparison to the past, and nothing about size or shape. They read these to each other. Then they talk about what has changed in how they touch and what they want back. Keep it off appearance verdicts; it is about closeness.', '[{"id": "f0", "type": "textarea", "label": "Partner one: what I fear my partner thinks about my body now:"}, {"id": "f1", "type": "textarea", "label": "Partner two: what I fear my partner thinks about my body now:"}, {"id": "f2", "type": "textarea", "label": "Partner one: what I actually notice and value about my partner''s body and presence, with no grading:"}, {"id": "f3", "type": "textarea", "label": "Partner two: what I actually notice and value about my partner''s body and presence, with no grading:"}, {"id": "f4", "type": "textarea", "label": "What has changed in how we touch each other over the years, and what each of us wants back:"}, {"id": "f5", "type": "textarea", "label": "One thing we will do differently this week because of this conversation:"}]'::jsonb, array['body image', 'couples', 'acceptance']::text[], '2026-11-16T15:00:00+00:00'::timestamptz)
